import React, { useMemo, useState } from 'react';
import { Project, Milestone, Lookup, Language, User } from '../types';
import SearchableSelect from './SearchableSelect';

interface KPIDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    projectManagers: User[];
    customers: Lookup[];
    countries: Lookup[];
    language: Language;
}

const KPIDashboard: React.FC<KPIDashboardProps> = ({ projects, milestones, teams, projectManagers, countries, language }) => {
    const t = translations[language];
    const [selectedManager, setSelectedManager] = useState('all');
    const [selectedCountry, setSelectedCountry] = useState('all');
    const [metricType, setMetricType] = useState<'count' | 'amount'>('count');
    const [region, setRegion] = useState('ALL');

    const regions = ['ALL', 'Levant', 'GCC', 'N. Africa', 'E. Africa'];

    // فلاتر الخيارات
    const countryOptions = useMemo(() => [
        { value: 'all', label: t.selectCountry },
        ...countries.map(c => ({ value: c.id, label: c.name }))
    ], [countries, t.selectCountry]);

    const managerOptions = useMemo(() => [
        { value: 'all', label: t.selectProjectManager },
        ...projectManagers.map(m => ({ value: m.id, label: m.name }))
    ], [projectManagers, t.selectProjectManager]);

    // حساب البيانات الحقيقية للرسوم البيانية
    const filteredProjects = useMemo(() => {
        return projects.filter(p => {
            const managerMatch = selectedManager === 'all' || p.projectManagerId === selectedManager;
            const countryMatch = selectedCountry === 'all' || p.countryId === selectedCountry;
            return managerMatch && countryMatch;
        });
    }, [projects, selectedManager, selectedCountry]);

    const initiationData = useMemo(() => {
        const counts: Record<string, number> = { '2025': 0, '2024': 0, 'Before': 0 };
        filteredProjects.forEach(p => {
            if (!p.actualStartDate) { counts['Before']++; return; }
            const year = new Date(p.actualStartDate).getFullYear();
            if (year === 2025) counts['2025']++;
            else if (year === 2024) counts['2024']++;
            else counts['Before']++;
        });
        const total = filteredProjects.length || 1;
        return [
            { label: '2025', value: counts['2025'], color: 'text-indigo-600', pct: (counts['2025']/total)*100 },
            { label: '2024', value: counts['2024'], color: 'text-blue-500', pct: (counts['2024']/total)*100 },
            { label: 'Older', value: counts['Before'], color: 'text-slate-400', pct: (counts['Before']/total)*100 },
        ];
    }, [filteredProjects]);

    const statusData = useMemo(() => {
        const stats: Record<string, number> = { 'Active': 0, 'Completed': 0, 'Hold': 0, 'Cancelled': 0 };
        filteredProjects.forEach(p => {
            const s = p.status?.name;
            if (s === 'Active' || s === 'نشط') stats['Active']++;
            else if (s === 'Completed' || s === 'مكتمل') stats['Completed']++;
            else if (s === 'On Hold' || s === 'متوقف') stats['Hold']++;
            else stats['Cancelled']++;
        });
        return [
            { label: 'Active', val: stats['Active'], color: 'bg-indigo-600' },
            { label: 'Done', val: stats['Completed'], color: 'bg-emerald-500' },
            { label: 'Hold', val: stats['Hold'], color: 'bg-orange-400' },
            { label: 'Cancl', val: stats['Cancelled'], color: 'bg-red-400' },
        ];
    }, [filteredProjects]);

    const SectionHeader = ({ title }: { title: string }) => (
        <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase mb-6 tracking-[0.2em]">{title}</h3>
    );

    const DonutChart = ({ data, total }: { data: any[], total: number }) => (
        <div className="relative flex flex-col items-center">
            <div className="w-40 h-40 rounded-full border-[16px] border-slate-100 dark:border-slate-800/50 flex items-center justify-center relative shadow-inner">
                <svg className="absolute inset-0 w-full h-full -rotate-90">
                    {data.map((item, i) => {
                        let offset = 0;
                        for(let j=0; j<i; j++) offset += data[j].pct;
                        return (
                            <circle key={i} cx="50%" cy="50%" r="42%" fill="transparent" stroke="currentColor" strokeWidth="16" 
                                className={item.color.replace('text-', 'stroke-')} 
                                strokeDasharray={`${item.pct} 100`} 
                                strokeDashoffset={-offset} 
                                strokeLinecap="round"
                            />
                        );
                    })}
                </svg>
                <div className="text-center z-10 bg-white dark:bg-slate-900 rounded-full w-24 h-24 flex flex-col items-center justify-center shadow-lg">
                    <span className="text-[9px] text-slate-400 uppercase font-black">{t.total}</span>
                    <span className="text-xl font-black text-slate-800 dark:text-white leading-none">{total}</span>
