                            <span className="text-slate-500">{item.label}</span>
                        </div>
                        <span className="text-slate-800 dark:text-white">{item.value} ({Math.round(item.pct)}%)</span>
                    </div>
                ))}
            </div>
        </div>
    );

    return (
        <div className="space-y-8 animate-in fade-in duration-700" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            {/* Header Filters */}
            <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border border-slate-100 dark:border-slate-800 p-6 rounded-[2.5rem] flex flex-wrap items-center justify-between gap-6 shadow-sm">
                <div className="flex items-center gap-3 overflow-x-auto no-scrollbar pb-1">
                    {regions.map(r => (
                        <button 
                            key={r} 
                            onClick={() => setRegion(r)}
                            className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${region === r ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'}`}
                        >
                            {r}
                        </button>
                    ))}
                </div>

                <div className="flex items-center gap-4 flex-1 justify-end">
                    <div className="w-48">
                        <SearchableSelect options={countryOptions} value={selectedCountry} onChange={setSelectedCountry} placeholder={t.selectCountry} language={language} />
                    </div>
                    <div className="w-56">
                        <SearchableSelect options={managerOptions} value={selectedManager} onChange={setSelectedManager} placeholder={t.selectProjectManager} language={language} />
                    </div>
                </div>
            </div>

            {/* Main Stats Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Left Column: Two Donut Charts */}
                <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="bg-white dark:bg-[#1e293b] p-8 rounded-[2.5rem] shadow-sm border border-slate-50 dark:border-slate-800 transition-all hover:shadow-xl">
                        <SectionHeader title={t.initiationYear} />
                        <DonutChart data={initiationData} total={filteredProjects.length} />
                    </div>
                    <div className="bg-white dark:bg-[#1e293b] p-8 rounded-[2.5rem] shadow-sm border border-slate-50 dark:border-slate-800 transition-all hover:shadow-xl">
                        <SectionHeader title={t.clientClassification} />
                        <DonutChart data={[
                            {label:'Enterprise', value: Math.round(filteredProjects.length * 0.4), color:'text-indigo-600', pct: 40}, 
                            {label:'SME', value: Math.round(filteredProjects.length * 0.4), color:'text-violet-500', pct: 40}, 
                            {label:'Gov', value: Math.round(filteredProjects.length * 0.2), color:'text-blue-400', pct: 20}
                        ]} total={filteredProjects.length} />
                    </div>
                </div>

                {/* Performance Vertical Bar */}
                <div className="lg:col-span-4 bg-white dark:bg-[#1e293b] p-8 rounded-[2.5rem] shadow-sm border border-slate-50 dark:border-slate-800">
                    <SectionHeader title={t.statusPerformance} />
                    <div className="h-64 flex items-end justify-between gap-4 px-2 mb-8">
                        {statusData.map((s, i) => (
                            <div key={i} className="flex-1 flex flex-col items-center gap-3 group">
