export default Header;

import React, { useMemo, useState } from 'react';
import { Project, Milestone, Lookup, Language, User, PaymentStatus } from '../types';
import SearchableSelect from './SearchableSelect';

interface KPIDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    projectManagers: User[];
    customers: Lookup[];
    countries: Lookup[];
    language: Language;
}

const KPIDashboard: React.FC<KPIDashboardProps> = ({ projects, milestones, projectManagers, language }) => {
    const t = translations[language];

    // States for Filters
    const [projectSearch, setProjectSearch] = useState('');
    const [selectedManager, setSelectedManager] = useState('all');
    const [selectedMonthYear, setSelectedMonthYear] = useState('all');

    // 1. توليد خيارات الشهر/السنة مرتبة تصاعدياً
    const monthYearOptions = useMemo(() => {
        const uniqueMonthYears = new Set<string>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
                uniqueMonthYears.add(key);
            }
        });

        const sortedKeys = Array.from(uniqueMonthYears).sort((a, b) => a.localeCompare(b));

        return [
            { value: 'all', label: t.allTime },
            ...sortedKeys.map(key => {
                const [year, month] = key.split('-').map(Number);
                const label = new Date(year, month - 1).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long', year: 'numeric' });
                return { value: key, label };
            })
        ];
    }, [milestones, language, t.allTime]);

    // 2. تصفية المعالم بناءً على الفترة الزمنية المختارة
    const filteredMilestones = useMemo(() => {
        return milestones.filter(m => {
            if (selectedMonthYear === 'all') return true;
            if (!m.dueDate) return false;
            const date = new Date(m.dueDate);
            const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
            return key === selectedMonthYear;
        });
    }, [milestones, selectedMonthYear]);

    // 3. حساب مبالغ المشاريع بناءً على المعالم المفلترة
    const projectFinancials = useMemo(() => {
        const map: Record<string, number> = {};
        filteredMilestones.forEach(m => {
            if (m.hasPayment) {
                map[m.projectId] = (map[m.projectId] || 0) + (m.paymentAmount || 0);
            }
        });
        return map;
    }, [filteredMilestones]);

    // 4. تطبيق فلاتر البحث والمدير
    const filteredProjects = useMemo(() => {
        return projects.filter(p => {
            const nameMatch = p.name.toLowerCase().includes(projectSearch.toLowerCase()) || 
                             p.projectCode.toLowerCase().includes(projectSearch.toLowerCase());
            const managerMatch = selectedManager === 'all' || p.projectManagerId === selectedManager;
            // إظهار المشاريع التي لها مبالغ في الفترة المحددة أو الكل إذا لم يتم اختيار فترة
            const hasFinancialsInPeriod = selectedMonthYear === 'all' || (projectFinancials[p.id] !== undefined);

            return nameMatch && managerMatch && hasFinancialsInPeriod;
        });
    }, [projects, projectSearch, selectedManager, selectedMonthYear, projectFinancials]);

    // 5. إحصائيات المؤشرات الرئيسية (KPIs)
    const kpis = useMemo(() => {
        const displayedProjectIds = new Set(filteredProjects.map(p => p.id));
        const totalValue = filteredProjects.reduce((sum, p) => sum + (projectFinancials[p.id] || 0), 0);

        const collected = filteredMilestones
            .filter(m => displayedProjectIds.has(m.projectId) && m.paymentStatus === PaymentStatus.Paid)
            .reduce((sum, m) => sum + (m.paymentAmount || 0), 0);

        const avgProgress = filteredProjects.length > 0 
            ? Math.round(filteredProjects.reduce((sum, p) => sum + (p.progress || 0), 0) / filteredProjects.length)
            : 0;

        return {
            totalValue,
            collected,
            pending: totalValue - collected,
            avgProgress,
            count: filteredProjects.length
        };
    }, [filteredProjects, projectFinancials, filteredMilestones]);

    // 6. تجميع البيانات حسب الشهر/السنة للرسم البياني (Sorted Trend Ascending)
    const monthlyTrend = useMemo(() => {
        const trend: Record<string, number> = {};
        const displayedIds = new Set(filteredProjects.map(p => p.id));

        // نستخدم كافة المعالم للمشاريع الظاهرة لرسم التريند العام، 
        // أو المعالم المفلترة فقط إذا أردت التركيز على نقطة واحدة
        const sourceMilestones = selectedMonthYear === 'all' ? milestones : filteredMilestones;

        sourceMilestones.forEach(m => {
            if (displayedIds.has(m.projectId) && m.dueDate) {
                const date = new Date(m.dueDate);
                const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
                trend[key] = (trend[key] || 0) + (m.paymentAmount || 0);
            }
        });

        return Object.entries(trend)
            .sort(([a], [b]) => a.localeCompare(b)) // الترتيب التصاعدي (Ascending)
            .map(([date, value]) => {
                const [y, m] = date.split('-');
                const label = new Date(parseInt(y), parseInt(m) - 1).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short', year: '2-digit' });
                return { label, value, rawDate: date };
            }).slice(-12); // آخر 12 شهراً متاحة
    }, [filteredProjects, milestones, filteredMilestones, selectedMonthYear, language]);

    const maxTrendValue = Math.max(...monthlyTrend.map(d => d.value), 1);

    const managerOptions = useMemo(() => [
        { value: 'all', label: t.allManagers },
        ...projectManagers.map(m => ({ value: m.id, label: m.name }))
    ], [projectManagers, t.allManagers]);

    const formatCurrency = (val: number) => 
        val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <div className="space-y-8 animate-in fade-in duration-500" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            {/* Top Filter Bar */}
            <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border border-slate-100 dark:border-slate-800 p-6 rounded-[2.5rem] shadow-sm flex flex-wrap items-center gap-4">
                <div className="flex-1 min-w-[240px] relative">
                    <span className="absolute inset-y-0 left-4 rtl:left-auto rtl:right-4 flex items-center pointer-events-none text-slate-400">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </span>
                    <input 
                        type="text" 
                        value={projectSearch}
                        onChange={(e) => setProjectSearch(e.target.value)}
                        placeholder={t.searchByProject}
                        className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl py-3 pl-12 pr-4 rtl:pr-12 rtl:pl-4 text-sm font-bold focus:ring-2 focus:ring-indigo-500 shadow-inner"
                    />
                </div>
                <div className="w-60">
                    <SearchableSelect options={managerOptions} value={selectedManager} onChange={setSelectedManager} placeholder={t.projectManager} language={language} />
                </div>
                <div className="w-60">
                    <SearchableSelect options={monthYearOptions} value={selectedMonthYear} onChange={setSelectedMonthYear} placeholder={t.period} language={language} />
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-8 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden group">
                    <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:scale-150 transition-transform"></div>
                    <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-2">{t.totalAmount}</p>
                    <p className="text-3xl font-black">{formatCurrency(kpis.totalValue)}</p>
                    <div className="mt-4 pt-4 border-t border-white/10 flex justify-between items-center text-[10px] font-bold">
                        <span>{kpis.count} {t.projects}</span>
                        <span className="bg-white/20 px-2 py-1 rounded-lg uppercase">{selectedMonthYear === 'all' ? 'All Time' : 'Period View'}</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm group">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.collected}</p>
                    <p className="text-3xl font-black text-emerald-500">{formatCurrency(kpis.collected)}</p>
                    <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full mt-6 overflow-hidden shadow-inner">
                        <div className="bg-emerald-500 h-full rounded-full transition-all duration-1000" style={{ width: `${(kpis.collected/kpis.totalValue)*100 || 0}%` }}></div>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.pending}</p>
                    <p className="text-3xl font-black text-orange-500">{formatCurrency(kpis.pending)}</p>
                    <p className="text-[10px] font-bold text-slate-400 mt-4 uppercase tracking-tighter italic">Remaining Balance</p>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.avgProgress}</p>
                    <p className="text-3xl font-black text-indigo-600">{kpis.avgProgress}%</p>
                    <div className="flex gap-1 mt-6">
                        {[1,2,3,4,5].map(i => (
                            <div key={i} className={`h-1.5 flex-1 rounded-full ${i <= (kpis.avgProgress/20) ? 'bg-indigo-500' : 'bg-slate-100 dark:bg-slate-800'}`}></div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Financial Trend Section */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-8 bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex justify-between items-center mb-10">
                        <div>
                            <h3 className="text-lg font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.financialTrend}</h3>
                            <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{t.monthlyBreakdown}</p>
                        </div>
                    </div>

                    <div className="h-72 flex items-end justify-between gap-4 px-2">
                        {monthlyTrend.length > 0 ? monthlyTrend.map((d, i) => (
                            <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                                <div className="absolute bottom-full mb-2 bg-slate-800 text-white text-[9px] font-black px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity z-10 whitespace-nowrap">
                                    {formatCurrency(d.value)}
                                </div>
                                <div 
                                    style={{ height: `${(d.value / maxTrendValue) * 100}%` }} 
                                    className={`w-full max-w-[40px] rounded-t-xl transition-all duration-700 shadow-lg ${d.rawDate === selectedMonthYear ? 'bg-gradient-to-t from-emerald-600 to-emerald-400' : 'bg-gradient-to-t from-indigo-600 to-violet-400 hover:from-indigo-500'} shadow-indigo-500/10`}
                                ></div>
                                <span className={`mt-4 text-[8px] font-black uppercase rotate-45 sm:rotate-0 ${d.rawDate === selectedMonthYear ? 'text-emerald-600 underline' : 'text-slate-400'}`}>{d.label}</span>
                            </div>
                        )) : (
                            <div className="w-full h-full flex items-center justify-center opacity-20 italic font-black uppercase tracking-[0.4em]">{t.noData}</div>
                        )}
                    </div>
                </div>

                {/* Top Projects by Value */}
                <div className="lg:col-span-4 bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase mb-8 tracking-widest border-b border-slate-50 dark:border-slate-800 pb-4">{t.topProjects}</h3>
                    <div className="space-y-6">
                        {filteredProjects.slice(0, 5).sort((a,b) => (projectFinancials[b.id]||0) - (projectFinancials[a.id]||0)).map((p, idx) => (
                            <div key={p.id} className="flex items-center justify-between group">
                                <div className="min-w-0">
                                    <p className="text-xs font-black text-slate-800 dark:text-white truncate group-hover:text-indigo-500 transition-colors">{p.name}</p>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">{p.projectCode}</p>
                                </div>
                                <div className="text-right shrink-0">
                                    <p className="text-xs font-black text-slate-800 dark:text-white">{formatCurrency(projectFinancials[p.id] || 0)}</p>
                                    <div className="flex items-center gap-1 justify-end">
                                        <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                                        <span className="text-[8px] font-black text-slate-400">{p.progress}%</span>
                                    </div>
                                </div>
                            </div>
                        ))}
                        {filteredProjects.length === 0 && <p className="text-center text-[10px] font-bold text-slate-300 uppercase py-10 tracking-widest">{t.noData}</p>}
                    </div>
                </div>
            </div>
        </div>
    );
};

