        });

        return Object.entries(trend)
            .sort(([a], [b]) => a.localeCompare(b))
            .map(([date, value]) => {
                const [y, m] = date.split('-');
                const label = new Date(parseInt(y), parseInt(m) - 1).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short', year: '2-digit' });
                return { label, value, rawDate: date };
            }).slice(-12);
    }, [filteredProjects, filteredMilestones, language]);

    const maxTrendValue = Math.max(...monthlyTrend.map(d => d.value), 1);

    const toggleProjectExpansion = (projectId: string) => {
        setExpandedProjects(prev => ({ ...prev, [projectId]: !prev[projectId] }));
    };

    const formatCurrency = (val: number) => 
        val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    const statusColors = {
        [MilestoneStatus.Completed]: 'text-emerald-500 bg-emerald-500/10',
        [MilestoneStatus.InProgress]: 'text-indigo-500 bg-indigo-500/10',
        [MilestoneStatus.Pending]: 'text-orange-500 bg-orange-500/10',
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            {/* Top Filter Bar */}
            <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border border-slate-100 dark:border-slate-800 p-6 rounded-[2.5rem] shadow-sm flex flex-wrap items-center gap-4">
                <div className="flex-1 min-w-[240px] relative">
                    <span className="absolute inset-y-0 left-4 rtl:left-auto rtl:right-4 flex items-center pointer-events-none text-slate-400">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </span>
                    <input 
                        type="text" 
                        value={projectSearch}
                        onChange={(e) => setProjectSearch(e.target.value)}
                        placeholder={t.searchByProject}
                        className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl py-3 pl-12 pr-4 rtl:pr-12 rtl:pl-4 text-sm font-bold focus:ring-2 focus:ring-indigo-500 shadow-inner"
                    />
                </div>
                <div className="w-60">
                    <SearchableSelect options={[{ value: 'all', label: t.allManagers }, ...projectManagers.map(m => ({ value: m.id, label: m.name }))]} value={selectedManager} onChange={setSelectedManager} placeholder={t.projectManager} language={language} />
                </div>
                <div className="w-60">
                    <SearchableSelect options={monthYearOptions} value={selectedMonthYear} onChange={setSelectedMonthYear} placeholder={t.period} language={language} />
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-8 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden group">
                    <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:scale-150 transition-transform"></div>
                    <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-2">{t.totalAmount}</p>
                    <p className="text-3xl font-black">{formatCurrency(kpis.totalValue)}</p>
                    <div className="mt-4 pt-4 border-t border-white/10 flex justify-between items-center text-[10px] font-bold">
                        <span>{kpis.count} {t.projects}</span>
                        <span className="bg-white/20 px-2 py-1 rounded-lg uppercase">{selectedMonthYear === 'all' ? 'All Time' : 'Period View'}</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm group">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.collected}</p>
                    <p className="text-3xl font-black text-emerald-500">{formatCurrency(kpis.collected)}</p>
                    <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full mt-6 overflow-hidden">
                        <div className="bg-emerald-500 h-full rounded-full transition-all duration-1000" style={{ width: `${(kpis.collected/kpis.totalValue)*100 || 0}%` }}></div>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.pending}</p>
                    <p className="text-3xl font-black text-orange-500">{formatCurrency(kpis.pending)}</p>
                    <p className="text-[10px] font-bold text-slate-400 mt-4 uppercase tracking-tighter italic">Remaining Balance</p>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.avgProgress}</p>
                    <p className="text-3xl font-black text-indigo-600">{kpis.avgProgress}%</p>
                    <div className="flex gap-1 mt-6">
                        {[1,2,3,4,5].map(i => (
                            <div key={i} className={`h-1.5 flex-1 rounded-full ${i <= (kpis.avgProgress/20) ? 'bg-indigo-500' : 'bg-slate-100 dark:bg-slate-800'}`}></div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Tree View Roadmap Section */}
            <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                <div className="flex justify-between items-end mb-10">
                    <div>
                        <h3 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.timelineRoadmap}</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{t.roadmapSubtitle}</p>
                    </div>
                    <div className="text-[10px] font-black text-violet-600 bg-violet-50 dark:bg-violet-900/20 px-4 py-2 rounded-xl">
                        {selectedMonthYear === 'all' ? t.allTime : monthYearOptions.find(o => o.value === selectedMonthYear)?.label}
                    </div>
                </div>

                <div className="space-y-4">
                    {filteredProjects.length > 0 ? filteredProjects.map(project => {
                        const projectMilestones = filteredMilestones.filter(m => m.projectId === project.id);
                        const isExpanded = !!expandedProjects[project.id];
                        const manager = projectManagers.find(m => m.id === project.projectManagerId);

                        return (
                            <div key={project.id} className="border border-slate-50 dark:border-slate-800 rounded-3xl overflow-hidden transition-all duration-300">
                                {/* Project Header (Parent) */}
                                <div 
                                    onClick={() => toggleProjectExpansion(project.id)}
                                    className={`p-5 flex items-center justify-between cursor-pointer transition-colors ${isExpanded ? 'bg-slate-50 dark:bg-slate-800/50' : 'bg-white dark:bg-slate-900 hover:bg-slate-50'}`}
                                >
                                    <div className="flex items-center gap-5 min-w-0">
                                        <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${isExpanded ? 'bg-violet-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                                            <svg className={`w-5 h-5 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 9l-7 7-7-7" /></svg>
                                        </div>
                                        <div className="min-w-0">
                                            <h4 className="font-black text-slate-800 dark:text-white truncate">{project.name}</h4>
                                            <div className="flex items-center gap-3 mt-1">
                                                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{project.projectCode}</span>
                                                <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                                                <div className="flex items-center gap-1.5">
                                                    <img src={manager?.avatarUrl || `https://ui-avatars.com/api/?name=${manager?.name || '?'}&background=8b5cf6&color=fff`} className="w-4 h-4 rounded-full" alt={manager?.name} />
                                                    <span className="text-[9px] font-bold text-slate-500">{manager?.name || t.unassigned}</span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-6">
                                        <div className="hidden sm:block text-right">
                                            <p className="text-[9px] font-black text-slate-400 uppercase">{t.progress}</p>
                                            <p className="text-xs font-black text-indigo-600">{project.progress}%</p>
                                        </div>
                                        <div className="text-right min-w-[80px]">
                                            <p className="text-[9px] font-black text-slate-400 uppercase">{t.items}</p>
                                            <p className="text-xs font-black text-slate-800 dark:text-white">{projectMilestones.length}</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Milestones List (Children) */}
                                {isExpanded && (
                                    <div className="p-4 bg-white dark:bg-slate-950 border-t border-slate-50 dark:border-slate-800 animate-in slide-in-from-top-2 duration-300">
                                        <div className="space-y-2 ps-12 relative">
                                            {/* Vertical Line Connector */}
                                            <div className="absolute left-6 rtl:left-auto rtl:right-6 top-0 bottom-6 w-0.5 bg-slate-100 dark:bg-slate-800"></div>

                                            {projectMilestones.map((m, idx) => (
                                                <div key={m.id} className="group flex items-center justify-between p-4 bg-slate-50/50 dark:bg-slate-900/30 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 transition-all border border-transparent hover:border-slate-100 dark:hover:border-slate-800">
                                                    <div className="flex items-center gap-4 min-w-0">
                                                        <div className="w-2 h-2 rounded-full bg-violet-400 shrink-0 group-hover:scale-125 transition-transform"></div>
                                                        <div className="min-w-0">
                                                            <p className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate">{m.title}</p>
                                                            <div className="flex items-center gap-3 mt-1">
                                                                <span className={`text-[8px] font-black px-2 py-0.5 rounded-md uppercase ${statusColors[m.status]}`}>{t[m.status]}</span>
                                                                {m.dueDate && <span className="text-[9px] font-bold text-slate-400">{new Date(m.dueDate).toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short' })}</span>}
                                                            </div>
                                                        </div>
                                                    </div>
                                                    {m.hasPayment && (
                                                        <div className="text-right">
                                                            <p className="text-xs font-black text-emerald-600">{formatCurrency(m.paymentAmount)}</p>
                                                            <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">{t[m.paymentStatus || 'Pending']}</p>
                                                        </div>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    }) : (
                        <div className="py-20 text-center text-[10px] font-black text-slate-300 uppercase tracking-[0.5em]">{t.noData}</div>
                    )}
                </div>
            </div>

            {/* Financial Trend & Top Projects */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-8 bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex justify-between items-center mb-10">
                        <div>
                            <h3 className="text-lg font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.financialTrend}</h3>
                            <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{t.monthlyBreakdown}</p>
                        </div>
                    </div>

                    <div className="h-72 flex items-end justify-between gap-4 px-2">
                        {monthlyTrend.length > 0 ? monthlyTrend.map((d, i) => (
                            <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                                <div className="absolute bottom-full mb-2 bg-slate-800 text-white text-[9px] font-black px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity z-10 whitespace-nowrap">
                                    {formatCurrency(d.value)}
                                </div>
                                <div 
                                    style={{ height: `${(d.value / maxTrendValue) * 100}%` }} 
                                    className={`w-full max-w-[40px] rounded-t-xl transition-all duration-700 shadow-lg ${d.rawDate === selectedMonthYear ? 'bg-gradient-to-t from-emerald-600 to-emerald-400' : 'bg-gradient-to-t from-indigo-600 to-violet-400 hover:from-indigo-500'} shadow-indigo-500/10`}
                                ></div>
                                <span className={`mt-4 text-[8px] font-black uppercase rotate-45 sm:rotate-0 ${d.rawDate === selectedMonthYear ? 'text-emerald-600 underline' : 'text-slate-400'}`}>{d.label}</span>
                            </div>
                        )) : (
                            <div className="w-full h-full flex items-center justify-center opacity-20 italic font-black uppercase tracking-[0.4em]">{t.noData}</div>
                        )}
                    </div>
                </div>

                <div className="lg:col-span-4 bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase mb-8 tracking-widest border-b border-slate-50 dark:border-slate-800 pb-4">{t.topProjects}</h3>
                    <div className="space-y-6">
                        {filteredProjects.slice(0, 5).map((p, idx) => (
                            <div key={p.id} className="flex items-center justify-between group">
                                <div className="min-w-0">
                                    <p className="text-xs font-black text-slate-800 dark:text-white truncate group-hover:text-indigo-500 transition-colors">{p.name}</p>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">{p.projectCode}</p>
                                </div>
                                <div className="text-right shrink-0">
                                    <p className="text-xs font-black text-slate-800 dark:text-white">{p.progress}%</p>
                                    <div className="flex items-center gap-1 justify-end">
                                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
                                        <span className="text-[8px] font-black text-slate-400 uppercase">ACTIVE</span>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

