        topProjects: "أعلى المشاريع قيمة", period: "الفترة الزمنية", allTime: "كل الأوقات", timelineRoadmap: "خارطة الطريق الزمنية",
        roadmapSubtitle: "هيكلية المشاريع والمعالم حسب الفترة المختارة", items: "معالم", progress: "التقدم", unassigned: "غير معين",
