                                                                        <div className="flex items-center gap-4 min-w-0">
                                                                            <div className="w-2 h-2 rounded-full bg-violet-400 shrink-0 group-hover:scale-125 transition-transform"></div>
                                                                            <div className="min-w-0">
                                                                                <p className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate">{m.title}</p>
                                                                                <div className="flex items-center gap-3 mt-1">
                                                                                    <span className={`text-[8px] font-black px-2 py-0.5 rounded-md uppercase ${statusColors[m.status]}`}>{t[m.status]}</span>
                                                                                    {m.dueDate && <span className="text-[9px] font-bold text-slate-400">{new Date(m.dueDate).toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short' })}</span>}
                                                                                </div>
                                                                            </div>
                                                                        </div>
                                                                        {m.hasPayment && (
                                                                            <div className="text-right">
                                                                                <p className="text-xs font-black text-emerald-600">{formatCurrency(m.paymentAmount)}</p>
                                                                                <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">{t[m.paymentStatus || 'Pending']}</p>
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        );
                    }) : (
                        <div className="py-20 text-center text-[10px] font-black text-slate-300 uppercase tracking-[0.5em]">{t.noData}</div>
                    )}
                </div>
            </div>

            {/* Financial Trend & Top Projects */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-8 bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex justify-between items-center mb-10">
                        <div>
                            <h3 className="text-lg font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.financialTrend}</h3>
                            <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{t.monthlyBreakdown}</p>
                        </div>
                    </div>

                    <div className="h-72 flex items-end justify-between gap-4 px-2">
                        {monthlyTrend.length > 0 ? monthlyTrend.map((d, i) => (
                            <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                                <div className="absolute bottom-full mb-2 bg-slate-800 text-white text-[9px] font-black px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity z-10 whitespace-nowrap">
                                    {formatCurrency(d.value)}
                                </div>
                                <div 
                                    style={{ height: `${(d.value / maxTrendValue) * 100}%` }} 
                                    className={`w-full max-w-[40px] rounded-t-xl transition-all duration-700 shadow-lg ${d.rawDate === selectedMonthYear ? 'bg-gradient-to-t from-emerald-600 to-emerald-400' : 'bg-gradient-to-t from-indigo-600 to-violet-400 hover:from-indigo-500'} shadow-indigo-500/10`}
                                ></div>
                                <span className={`mt-4 text-[8px] font-black uppercase rotate-45 sm:rotate-0 ${d.rawDate === selectedMonthYear ? 'text-emerald-600 underline' : 'text-slate-400'}`}>{d.label}</span>
