import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Session, SupabaseClient } from '@supabase/supabase-js';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import KPIDashboard from './components/KPIDashboard';
import Projects from './components/Projects';
import Milestones from './components/Milestones';
import Team from './components/Team';
import Payments from './components/Payments';
import MaintenanceContracts from './components/MaintenanceContracts';
import Issues from './components/Issues';
import SystemManagement from './components/SystemManagement';
import MilestoneFilter from './components/MilestoneFilter';
import ReportsBuilder from './components/ReportsBuilder';
import Login from './components/Login';
import EditProjectModal from './components/EditProjectModal';
import EditMilestoneModal from './components/EditMilestoneModal';
import MilestoneDetailModal from './components/MilestoneDetailModal';
import ConfirmDeleteModal from './components/ConfirmDeleteModal';
import Chatbot from './components/Chatbot';
import { Language, Theme, View, Project, Milestone, User, Lookups, MaintenanceContract, Issue, Notification, RolePermissions } from './types';
import { 
    fetchAllData, 
    addProject as apiAddProject, 
    updateProject as apiUpdateProject, 
    addMilestones as apiAddMilestones, 
    updateMilestone as apiUpdateMilestone, 
    updateLookups as apiUpdateLookups, 
    deleteProject as apiDeleteProject,
    addMaintenanceContract as apiAddContract,
    updateMaintenanceContract as apiUpdateContract,
    addIssue as apiAddIssue,
    updateIssue as apiUpdateIssue,
    addIssueComment as apiAddIssueComment,
} from './services/api';
import { initSupabase, getSupabase } from './services/supabaseClient';
import { analyzeQuery } from './services/geminiService';

const App: React.FC = () => {
    const [view, setView] = useState<View>(() => (localStorage.getItem('lastView') as View) || 'dashboard');
    const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('language') as Language) || 'en');
    const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'light');
    const [isLoading, setIsLoading] = useState(true);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    const [projects, setProjects] = useState<Project[]>([]);
    const [milestones, setMilestones] = useState<Milestone[]>([]);
    const [maintenanceContracts, setMaintenanceContracts] = useState<MaintenanceContract[]>([]);
    const [issues, setIssues] = useState<Issue[]>([]);
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [lookups, setLookups] = useState<Lookups>({ countries: [], categories: [], teams: [], products: [], projectStatuses: [], projectManagers: [], customers: [] });

    // Permissions State
    const [rolePermissions, setRolePermissions] = useState<RolePermissions[]>(() => {
        const saved = localStorage.getItem('rolePermissions');
        return saved ? JSON.parse(saved) : [
            { role: 'PM', allowedViews: ['dashboard', 'filter', 'projects', 'milestones', 'team', 'payments', 'reports', 'maintenanceContracts', 'system', 'issues'] },
            { role: 'PS', allowedViews: ['issues'] },
            { role: 'Staff', allowedViews: ['dashboard', 'projects', 'issues'] }
        ];
    });

    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);
    const [viewingMilestone, setViewingMilestone] = useState<Milestone | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [isChatbotOpen, setIsChatbotOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [isAnalyzing, setIsAnalyzing] = useState(false);

    const [session, setSession] = useState<Session | null>(null);
    const [supabaseClient, setSupabaseClient] = useState<SupabaseClient | null>(null);
    const [isAppConfigured, setIsAppConfigured] = useState(false);

    const isFetching = useRef(false);

    const currentUser = useMemo(() => users.find(u => u.id === session?.user?.id), [users, session]);

    // Role-based allowed views
    const allowedViews = useMemo(() => {
        if (!currentUser) return [];
        const config = rolePermissions.find(p => p.role === currentUser.type);
        return config ? config.allowedViews : [];
    }, [currentUser, rolePermissions]);

    // Security: Check if current view is allowed
    useEffect(() => {
        if (currentUser && allowedViews.length > 0 && !allowedViews.includes(view)) {
            setView(allowedViews[0]); // Redirect to first allowed view
        }
    }, [view, allowedViews, currentUser]);

    useEffect(() => { localStorage.setItem('lastView', view); }, [view]);
    useEffect(() => { localStorage.setItem('language', language); }, [language]);
    useEffect(() => {
        localStorage.setItem('theme', theme);
        document.documentElement.classList.toggle('dark', theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches));
    }, [theme]);

    const setupClient = useCallback((key: string, url: string) => {
        try {
            const client = initSupabase(url, key);
            setSupabaseClient(client);
            setIsAppConfigured(true);
            setErrorMsg(null);
            return true;
        } catch (e: any) {
            setErrorMsg(e.message || "Invalid Supabase Configuration");
            setIsAppConfigured(false);
            return false;
        }
    }, []);

    useEffect(() => {
        const key = localStorage.getItem('supabaseAnonKey');
        const url = localStorage.getItem('supabaseUrl') || 'https://dcamlinhazzmbaldsrdo.supabase.co';
        if (key?.trim()) setupClient(key, url);
        else { setIsAppConfigured(false); setIsLoading(false); }
    }, [setupClient]);

    useEffect(() => {
        if (!supabaseClient) return;
        supabaseClient.auth.getSession().then(({ data: { session } }) => {
            setSession(session);
            setIsLoading(false);
        });
        const { data: { subscription } } = supabaseClient.auth.onAuthStateChange((_event, session) => setSession(session));
        return () => subscription.unsubscribe();
    }, [supabaseClient]);

    const loadData = useCallback(async () => {
        if (!session || isFetching.current) return;
        try {
            isFetching.current = true;
            const data = await fetchAllData();
            setProjects(data.projects || []);
            setMilestones(data.milestones || []);
            setMaintenanceContracts(data.maintenanceContracts || []);
            setIssues(data.issues || []);
            setNotifications(data.notifications || []);
            setUsers(data.users || []);
            if (data.lookups) setLookups(data.lookups);
        } catch (e: any) {
            setErrorMsg("Database Connection Error.");
        } finally {
            isFetching.current = false;
        }
    }, [session]);

    useEffect(() => {
        if (session) {
            loadData();
            const sb = getSupabase();
            if (sb) {
                const channel = sb.channel('notif-updates')
                    .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications', filter: `user_id=eq.${session.user.id}` }, () => loadData())
                    .subscribe();
                return () => { sb.removeChannel(channel); };
            }
        }
    }, [session, loadData]);

    const handleAiSearch = async (query: string) => {
        if (!query.trim()) return;
        setIsAnalyzing(true);
        try {
            await analyzeQuery(query, projects, milestones, users, lookups.teams);
        } catch (err) {
            console.error(err);
        } finally {
            setIsAnalyzing(false);
        }
    };

    if (isLoading) return <div className="min-h-screen bg-white dark:bg-slate-950 flex items-center justify-center"><div className="w-10 h-10 border-4 border-violet-600/20 border-t-violet-600 rounded-full animate-spin"></div></div>;
    if (!isAppConfigured) return <SystemManagement lookups={lookups} onUpdate={() => {}} language={language} onSaveConfig={(k, u) => { localStorage.setItem('supabaseAnonKey', k); localStorage.setItem('supabaseUrl', u); setupClient(k, u); }} isSetupMode={true} rolePermissions={rolePermissions} onUpdatePermissions={() => {}} />;
    if (!session) return <Login onLoginSuccess={() => loadData()} language={language} setLanguage={setLanguage} supabaseClient={supabaseClient!} />;

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <Sidebar currentView={view} setCurrentView={setView} language={language} allowedViews={allowedViews} />

            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header 
                    user={currentUser} 
                    language={language} setLanguage={setLanguage} onSearch={handleAiSearch} onLogout={() => supabaseClient?.auth.signOut()} 
                    theme={theme} setTheme={setTheme} isDbConnected={!!session} onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                    notifications={notifications} onNotificationRead={loadData}
                />

                {isAnalyzing && <div className="h-0.5 w-full bg-violet-600/20 overflow-hidden"><div className="h-full bg-violet-600 animate-[loading_2s_ease-in-out_infinite]" style={{ width: '30%', transformOrigin: 'left' }}></div></div>}

                <main className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
                    {view === 'dashboard' && allowedViews.includes('dashboard') && <KPIDashboard projects={projects} milestones={milestones} issues={issues} allUsers={users} teams={lookups.teams} projectManagers={lookups.projectManagers} customers={lookups.customers} countries={lookups.countries} language={language} />}
                    {view === 'projects' && allowedViews.includes('projects') && <Projects allProjects={projects} allUsers={users} language={language} onAddProject={async (d) => { await apiAddProject(d); loadData(); }} onOpenEditModal={setEditingProject} onOpenDeleteModal={setDeletingProject} lookups={lookups} isImportModalOpen={isImportModalOpen} onOpenImportModal={() => setIsImportModalOpen(true)} onCloseImportModal={() => setIsImportModalOpen(false)} onImportProjects={async () => {}} />}
                    {view === 'milestones' && allowedViews.includes('milestones') && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} lookups={lookups} />}
                    {view === 'team' && allowedViews.includes('team') && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && allowedViews.includes('payments') && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'maintenanceContracts' && allowedViews.includes('maintenanceContracts') && <MaintenanceContracts contracts={maintenanceContracts} customers={lookups.customers} language={language} onAddContract={async (d) => { await apiAddContract(d); loadData(); }} onUpdateContract={async (id, d) => { await apiUpdateContract(id, d); loadData(); }} />}
                    {view === 'issues' && allowedViews.includes('issues') && <Issues allIssues={issues} allProjects={projects} allMilestones={milestones} allUsers={users} language={language} onAddIssue={async (d) => { await apiAddIssue(d); loadData(); }} onUpdateIssue={async (id, d) => { await apiUpdateIssue(id, d); loadData(); }} onAddComment={async (id, uid, c) => { await apiAddIssueComment(id, uid, c); loadData(); }} currentUser={currentUser} />}
                    {view === 'system' && allowedViews.includes('system') && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={(k, u) => { localStorage.setItem('supabaseAnonKey', k); localStorage.setItem('supabaseUrl', u); setupClient(k, u); }} rolePermissions={rolePermissions} onUpdatePermissions={(p) => { setRolePermissions(p); localStorage.setItem('rolePermissions', JSON.stringify(p)); }} />}
                    {view === 'filter' && allowedViews.includes('filter') && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'reports' && allowedViews.includes('reports') && <ReportsBuilder projects={projects} milestones={milestones} issues={issues} users={users} teams={lookups.teams} language={language} />}
                </main>
            </div>

            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={async (id, d) => { await apiUpdateProject(id, d); loadData(); }} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={[]} allUsers={users} currentUser={currentUser} onClose={() => setEditingMilestone(null)} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onAddUpdate={async () => {}} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={[]} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={async () => { await apiDeleteProject(deletingProject.id); setDeletingProject(null); loadData(); }} language={language} />}

            <Chatbot isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} language={language} projects={projects} milestones={milestones} users={users} lookups={lookups} />
            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-6 right-6 bg-slate-900 text-white p-4 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all z-40"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg></button>
            <style>{`@keyframes loading { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }`}</style>
        </div>
    );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Project, Milestone, Language, Lookup, Issue, User } from '../types';

interface Field {
    id: string;
    label: string;
    category: 'Project' | 'Milestone' | 'Issue' | 'User';
    accessor: (proj?: Project, mile?: Milestone, issue?: Issue, user?: User) => string | number | null;
}

interface ReportsBuilderProps {
    projects: Project[];
    milestones: Milestone[];
    issues: Issue[];
    users: User[];
    teams: Lookup[];
    language: Language;
}

type AggMeasure = 'count' | 'sum' | 'avg';

const ReportsBuilder: React.FC<ReportsBuilderProps> = ({ projects, milestones, issues, users, teams, language }) => {
    const [selectedFields, setSelectedFields] = useState<Field[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [rowFilters, setRowFilters] = useState<Record<string, string>>({});
    const [isAggregationMode, setIsAggregationMode] = useState(false);
    const [groupByFieldId, setGroupByFieldId] = useState<string>('proj_customer');
    const [aggMeasure, setAggMeasure] = useState<AggMeasure>('count');

    const t = translations[language];

    const AVAILABLE_FIELDS: Field[] = useMemo(() => [
        { id: 'proj_name', label: language === 'ar' ? 'اسم المشروع' : 'Project Name', category: 'Project', accessor: (p) => p?.name || '--' },
        { id: 'proj_code', label: language === 'ar' ? 'كود المشروع' : 'Project Code', category: 'Project', accessor: (p) => p?.projectCode || '--' },
        { id: 'proj_pm', label: language === 'ar' ? 'مدير المشروع' : 'Project Manager', category: 'Project', accessor: (p) => p?.projectManager?.name || '--' },
        { id: 'proj_customer', label: language === 'ar' ? 'العميل' : 'Customer', category: 'Project', accessor: (p) => p?.customer?.name || '--' },
        { id: 'proj_status', label: language === 'ar' ? 'حالة المشروع' : 'Project Status', category: 'Project', accessor: (p) => p?.status?.name || '--' },
        { id: 'proj_progress', label: language === 'ar' ? 'نسبة التقدم' : 'Progress', category: 'Project', accessor: (p) => p ? `${p.progress}%` : '--' },

        { id: 'mile_title', label: language === 'ar' ? 'عنوان المعلم' : 'Milestone Title', category: 'Milestone', accessor: (_, m) => m?.title || '--' },
        { id: 'mile_status', label: language === 'ar' ? 'حالة المعلم' : 'Milestone Status', category: 'Milestone', accessor: (_, m) => m?.status || '--' },
        { id: 'mile_amount', label: language === 'ar' ? 'قيمة الدفعة' : 'Milestone Value', category: 'Milestone', accessor: (_, m) => m?.hasPayment ? m.paymentAmount : '--' },

        { id: 'issue_title', label: language === 'ar' ? 'عنوان المشكلة' : 'Issue Title', category: 'Issue', accessor: (_, __, i) => i?.title || '--' },
        { id: 'issue_status', label: language === 'ar' ? 'حالة المشكلة' : 'Issue Status', category: 'Issue', accessor: (_, __, i) => i?.status || '--' },
        { id: 'issue_priority', label: language === 'ar' ? 'الأولوية' : 'Priority', category: 'Issue', accessor: (_, __, i) => i?.priority || '--' },
        { id: 'issue_assignee', label: language === 'ar' ? 'المسؤول عن الحل' : 'Assigned Agent', category: 'Issue', accessor: (_, __, i) => i?.assignee?.name || '--' },

        { id: 'user_name', label: language === 'ar' ? 'اسم الموظف' : 'User Name', category: 'User', accessor: (_, __, __, u) => u?.name || '--' },
        { id: 'user_role', label: language === 'ar' ? 'الدور الوظيفي' : 'Role', category: 'User', accessor: (_, __, __, u) => u?.type || '--' },

        { 
            id: 'team_name', 
            label: language === 'ar' ? 'الفريق' : 'Team', 
            category: 'Milestone', 
            accessor: (p, m) => {
                const teamId = m?.teamId || p?.teamId;
                return teams.find(t => t.id === teamId)?.name || '--';
            }
        },
        { id: 'proj_country', label: language === 'ar' ? 'الدولة' : 'Country', category: 'Project', accessor: (p) => p?.country?.name || '--' },
    ], [teams, language]);

    const filteredAvailableFields = AVAILABLE_FIELDS.filter(f => 
        !selectedFields.find(sf => sf.id === f.id) && 
        f.label.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleAddField = (field: Field) => {
        if (!selectedFields.find(f => f.id === field.id)) {
            setSelectedFields([...selectedFields, field]);
        }
    };

    const removeField = (fieldId: string) => {
        setSelectedFields(selectedFields.filter(f => f.id !== fieldId));
    };

    const reportData = useMemo(() => {
        const categories = new Set(selectedFields.map(f => f.category));

        if (!isAggregationMode) {
            let rows: any[] = [];

            // تحديد الكيان الأساسي للتقرير بناءً على الأولويات: Issue > Milestone > Project > User
            if (categories.has('Issue')) {
                issues.forEach(i => {
                    const row: any = {};
                    const proj = projects.find(p => p.id === i.projectId);
                    const user = users.find(u => u.id === i.assigneeId);
                    selectedFields.forEach(f => { row[f.id] = f.accessor(proj, undefined, i, user); });
                    rows.push(row);
                });
            } else if (categories.has('Milestone')) {
                milestones.forEach(m => {
                    const row: any = {};
                    const proj = projects.find(p => p.id === m.projectId);
                    selectedFields.forEach(f => { row[f.id] = f.accessor(proj, m, undefined, undefined); });
                    rows.push(row);
                });
            } else if (categories.has('Project')) {
                projects.forEach(p => {
                    const row: any = {};
                    const user = users.find(u => u.id === p.projectManagerId);
                    selectedFields.forEach(f => { row[f.id] = f.accessor(p, undefined, undefined, user); });
                    rows.push(row);
                });
            } else if (categories.has('User')) {
                users.forEach(u => {
                    const row: any = {};
                    selectedFields.forEach(f => { row[f.id] = f.accessor(undefined, undefined, undefined, u); });
                    rows.push(row);
                });
            }

            return rows.filter(row => {
                return Object.entries(rowFilters).every(([fieldId, filterValue]) => {
                    const val = filterValue as string;
                    if (!val) return true;
                    return String(row[fieldId] || '').toLowerCase().includes(val.toLowerCase());
                });
            });
        } else {
            // وضع الإحصائيات (Aggregation)
            const groupingField = AVAILABLE_FIELDS.find(f => f.id === groupByFieldId);
            if (!groupingField) return [];

            const aggMap = new Map<string, { label: string, count: number, sum: number }>();

            // التجميع قد يكون حسب المشروع، العميل، أو الموظف (كمدير مشروع)
            projects.forEach(p => {
                const label = String(groupingField.accessor(p, undefined, undefined, users.find(u => u.id === p.projectManagerId)) || '--');
                if (!aggMap.has(label)) aggMap.set(label, { label, count: 0, sum: 0 });

                const entry = aggMap.get(label)!;
                const pMilestones = milestones.filter(m => m.projectId === p.id);

                entry.count += pMilestones.length;
                entry.sum += pMilestones.reduce((s, m) => s + (m.hasPayment ? m.paymentAmount : 0), 0);
            });

            return Array.from(aggMap.values()).map(i => {
                const avg = i.count > 0 ? i.sum / i.count : 0;
                return {
                    [groupByFieldId]: i.label, 
                    'agg_count': i.count, 
                    'agg_sum': i.sum,
                    'agg_avg': avg,
                    'agg_sum_fmt': i.sum.toLocaleString(),
                    'agg_avg_fmt': avg.toLocaleString(undefined, { maximumFractionDigits: 2 })
                };
            }).sort((a, b) => {
                const key = `agg_${aggMeasure}`;
                return (b[key as keyof typeof b] as number) - (a[key as keyof typeof a] as number);
            });
        }
    }, [projects, milestones, issues, users, selectedFields, rowFilters, isAggregationMode, groupByFieldId, AVAILABLE_FIELDS, aggMeasure]);

    const displayColumns = useMemo(() => {
        if (!isAggregationMode) return selectedFields;
        const gField = AVAILABLE_FIELDS.find(f => f.id === groupByFieldId)!;
        return [
            gField, 
            { id: 'agg_count', label: t.metric_count }, 
            { id: 'agg_sum_fmt', label: t.totalValue }, 
            { id: 'agg_avg_fmt', label: t.avgValue }
        ] as any[];
    }, [isAggregationMode, selectedFields, groupByFieldId, AVAILABLE_FIELDS, t]);

    const graphMax = useMemo(() => {
        if (!isAggregationMode || reportData.length === 0) return 1;
        const key = `agg_${aggMeasure}`;
        return Math.max(...reportData.map(d => Number(d[key as keyof typeof d])), 1);
    }, [isAggregationMode, reportData, aggMeasure]);

    const formatGraphValue = (val: number) => {
        if (aggMeasure === 'count') return val.toString();
        return '$' + val.toLocaleString(undefined, { maximumFractionDigits: 0 });
    };

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-10">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{t.subtitle}</p>
                </div>
                <div className="flex items-center gap-2">
                    <div className="bg-slate-100 dark:bg-slate-800 p-1 rounded-xl flex gap-1">
                        <button onClick={() => setIsAggregationMode(false)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${!isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.detailedMode}</button>
                        <button onClick={() => setIsAggregationMode(true)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.aggMode}</button>
                    </div>
                    <button onClick={() => {}} className="px-6 py-2.5 bg-violet-600 text-white text-[9px] font-black uppercase tracking-widest rounded-xl hover:bg-violet-700 shadow-lg shadow-violet-500/20">{t.export}</button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                <div className="lg:col-span-3 space-y-4">
                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[650px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800">
                             <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">{t.availableFields}</h2>
                             <div className="relative">
                                <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder={t.searchPlaceholder} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl p-2.5 text-xs outline-none focus:ring-1 focus:ring-violet-500" />
                                <svg className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-2">
                            <div className="pb-4">
                                <h3 className="text-[8px] font-black text-violet-500 uppercase tracking-widest mb-3 ps-1">{t.projectSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'Project').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-violet-300 dark:hover:border-violet-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-violet-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="pb-4">
                                <h3 className="text-[8px] font-black text-blue-500 uppercase tracking-widest mb-3 ps-1">{t.milestoneSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'Milestone').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-blue-300 dark:hover:border-blue-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="pb-4">
                                <h3 className="text-[8px] font-black text-red-500 uppercase tracking-widest mb-3 ps-1">{t.issueSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'Issue').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-red-300 dark:hover:border-red-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <h3 className="text-[8px] font-black text-emerald-500 uppercase tracking-widest mb-3 ps-1">{t.userSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'User').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-emerald-300 dark:hover:border-emerald-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-emerald-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-9 space-y-6">
                    {isAggregationMode && reportData.length > 0 && (
                        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] shadow-sm animate-in fade-in slide-in-from-top-4">
                            <div className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4">
                                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.chartTitle}</h2>
                                <div className="flex gap-2 bg-slate-50 dark:bg-slate-800 p-1 rounded-xl">
                                    <button onClick={() => setAggMeasure('count')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'count' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_count}</button>
                                    <button onClick={() => setAggMeasure('sum')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'sum' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_sum}</button>
                                    <button onClick={() => setAggMeasure('avg')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'avg' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_avg}</button>
                                </div>
                            </div>

                            <div className="h-56 flex items-end gap-3 px-2">
                                {reportData.slice(0, 15).map((row, idx) => {
                                    const valKey = `agg_${aggMeasure}`;
                                    const val = Number(row[valKey as keyof typeof row]);
                                    const pct = (val / graphMax) * 100;
                                    return (
                                        <div key={idx} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                                            <div className="absolute bottom-full mb-2 bg-slate-800 text-white text-[9px] font-black px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none whitespace-nowrap">
                                                {row[groupByFieldId]}: {formatGraphValue(val)}
                                            </div>
                                            <div 
                                                style={{ height: `${Math.max(pct, 2)}%` }} 
                                                className="w-full max-w-[40px] bg-gradient-to-t from-violet-600 to-indigo-400 rounded-t-xl hover:from-violet-500 hover:to-indigo-300 transition-all duration-500 shadow-lg shadow-violet-500/10"
                                            ></div>
                                            <span className="mt-3 text-[7px] font-black text-slate-400 uppercase truncate w-full text-center">{row[groupByFieldId]}</span>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {!isAggregationMode && (
                        <div className="bg-slate-100/50 dark:bg-slate-900/40 border-2 border-dashed border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] min-h-[120px]">
                             <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 px-2">{t.dropZone}</h2>
                             <div className="flex flex-wrap gap-2">
                                {selectedFields.length === 0 ? (
                                    <div className="w-full text-center py-4 opacity-20 italic text-xs font-black uppercase tracking-widest">{t.dropHint}</div>
                                ) : selectedFields.map(field => (
                                    <div key={field.id} className="bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 px-4 py-2 rounded-xl shadow-sm flex items-center gap-3 animate-in zoom-in-95">
                                        <span className={`w-1.5 h-1.5 rounded-full ${field.category === 'Project' ? 'bg-violet-500' : field.category === 'Milestone' ? 'bg-blue-500' : field.category === 'Issue' ? 'bg-red-500' : 'bg-emerald-500'}`}></span>
                                        <span className="text-[10px] font-black text-slate-700 dark:text-slate-200">{field.label}</span>
                                        <button onClick={() => removeField(field.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                                            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                                        </button>
                                    </div>
                                ))}
                             </div>
                        </div>
                    )}

                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[500px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center bg-slate-50/30 dark:bg-slate-800/20">
                            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{t.preview}</h2>
                            <div className="flex items-center gap-4">
                                {isAggregationMode && (
                                    <div className="flex items-center gap-4">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[9px] font-black text-slate-400 uppercase">{t.groupBy}</span>
                                            <select value={groupByFieldId} onChange={e => setGroupByFieldId(e.target.value)} className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-1.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-violet-500 transition-all">
                                                {AVAILABLE_FIELDS.filter(f => f.category === 'Project' || f.category === 'User').map(f => <option key={f.id} value={f.id}>{f.label}</option>)}
                                            </select>
                                        </div>
                                    </div>
                                )}
                                <span className="text-[10px] font-black text-violet-600 bg-violet-50 dark:bg-violet-900/30 px-3 py-1 rounded-full uppercase">{reportData.length} {t.rowsCount}</span>
                            </div>
                        </div>
                        <div className="flex-1 overflow-auto custom-scrollbar">
                            <table className="w-full text-start border-collapse">
                                <thead className="sticky top-0 bg-white dark:bg-slate-900 z-10">
                                    <tr className="bg-slate-50 dark:bg-slate-800/50">
                                        {displayColumns.map(f => (
                                            <th key={f.id} className="px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-start whitespace-nowrap border-b border-slate-100 dark:border-slate-800">
                                                {f.label}
                                                {!isAggregationMode && (
                                                    <input type="text" value={rowFilters[f.id] || ''} onChange={e => setRowFilters(v => ({...v, [f.id]: (e.target as HTMLInputElement).value}))} placeholder={t.filterPlaceholder} className="block mt-2 w-full bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-md p-1.5 text-[8px] font-bold outline-none" />
                                                )}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                    {reportData.length > 0 ? reportData.map((row, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-colors">
                                            {displayColumns.map(f => (
                                                <td key={f.id} className={`px-5 py-3.5 text-[10px] font-bold whitespace-nowrap ${f.id.startsWith('agg_') ? 'text-violet-600 dark:text-violet-400' : 'text-slate-600 dark:text-slate-300'}`}>
                                                    {row[f.id as keyof typeof row]}
                                                </td>
                                            ))}
                                        </tr>
                                    )) : (
                                        <tr>
                                            <td colSpan={displayColumns.length} className="px-6 py-20 text-center text-[10px] font-black text-slate-200 uppercase tracking-[0.4em]">{t.noResults}</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const translations = {
    ar: {
        title: "بناء التقارير المخصصة", subtitle: "صمم تقاريرك الخاصة بسحب وإفلات الحقول المطلوبة.", availableFields: "قائمة الحقول", dropZone: "أعمدة التقرير المختارة", dropHint: "انقر على الحقول لإضافتها كأعمدة للتقرير", preview: "المعاينة المباشرة", export: "تصدير CSV", searchPlaceholder: "ابحث عن حقل...", clear: "تفريغ", noFields: "لم يتم اختيار أعمدة بعد.", filterPlaceholder: "تصفية...", noResults: "لا توجد بيانات مطابقة.", rowsCount: "سجل", detailedMode: "عرض تفصيلي", aggMode: "وضع الإحصائيات", groupBy: "تجميع حسب:", measureBy: "عرض المقياس:", metric_count: "العدد (Count)", metric_sum: "المجموع (Sum)", metric_avg: "المتوسط (Avg)", projectSource: "مشروع", milestoneSource: "معلم/دفعة", issueSource: "الأعطال (Issues)", userSource: "الموظفون", chartTitle: "التمثيل البياني للإحصائيات", valueLabel: "القيمة", totalValue: "إجمالي القيمة", avgValue: "متوسط القيمة"
    },
    en: {
        title: "Custom Report Builder", subtitle: "Design your custom reports by selecting fields.", availableFields: "Field Library", dropZone: "Selected Columns", dropHint: "Click fields from the library to add them to your report", preview: "Live Preview", export: "Export CSV", searchPlaceholder: "Search fields...", clear: "Clear", noFields: "No columns selected.", filterPlaceholder: "Filter...", noResults: "No results found.", rowsCount: "Rows", detailedMode: "Detailed View", aggMode: "Analytics Mode", groupBy: "Group By:", measureBy: "Measure:", metric_count: "Count", metric_sum: "Sum", metric_avg: "Average", projectSource: "Project", milestoneSource: "Milestone", issueSource: "Issues", userSource: "Users", chartTitle: "Analytics Visualization", valueLabel: "Value", totalValue: "Total Value", avgValue: "Avg Value"
    }
};

export default ReportsBuilder;

import React, { useState, useMemo } from 'react';
import { Project, Milestone, Language, Lookup, Issue, User } from '../types';

interface Field {
    id: string;
    label: string;
    category: 'Project' | 'Milestone' | 'Issue' | 'User';
    accessor: (proj?: Project, mile?: Milestone, issue?: Issue, user?: User) => string | number | null;
}

interface ReportsBuilderProps {
    projects: Project[];
    milestones: Milestone[];
    issues: Issue[];
    users: User[];
    teams: Lookup[];
    language: Language;
}

type AggMeasure = 'count' | 'sum' | 'avg';

const ReportsBuilder: React.FC<ReportsBuilderProps> = ({ projects, milestones, issues, users, teams, language }) => {
    const [selectedFields, setSelectedFields] = useState<Field[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [rowFilters, setRowFilters] = useState<Record<string, string>>({});
    const [isAggregationMode, setIsAggregationMode] = useState(false);
    const [groupByFieldId, setGroupByFieldId] = useState<string>('proj_customer');
    const [aggMeasure, setAggMeasure] = useState<AggMeasure>('count');

    const t = translations[language];

    const AVAILABLE_FIELDS: Field[] = useMemo(() => [
        { id: 'proj_name', label: language === 'ar' ? 'اسم المشروع' : 'Project Name', category: 'Project', accessor: (p) => p?.name || '--' },
        { id: 'proj_code', label: language === 'ar' ? 'كود المشروع' : 'Project Code', category: 'Project', accessor: (p) => p?.projectCode || '--' },
        { id: 'proj_pm', label: language === 'ar' ? 'مدير المشروع' : 'Project Manager', category: 'Project', accessor: (p) => p?.projectManager?.name || '--' },
        { id: 'proj_customer', label: language === 'ar' ? 'العميل' : 'Customer', category: 'Project', accessor: (p) => p?.customer?.name || '--' },
        { id: 'proj_status', label: language === 'ar' ? 'حالة المشروع' : 'Project Status', category: 'Project', accessor: (p) => p?.status?.name || '--' },
        { id: 'proj_progress', label: language === 'ar' ? 'نسبة التقدم' : 'Progress', category: 'Project', accessor: (p) => p ? `${p.progress}%` : '--' },

        // Use unique unused parameter names to avoid "Duplicate identifier" errors
        { id: 'mile_title', label: language === 'ar' ? 'عنوان المعلم' : 'Milestone Title', category: 'Milestone', accessor: (_p, m) => m?.title || '--' },
        { id: 'mile_status', label: language === 'ar' ? 'حالة المعلم' : 'Milestone Status', category: 'Milestone', accessor: (_p, m) => m?.status || '--' },
        { id: 'mile_amount', label: language === 'ar' ? 'قيمة الدفعة' : 'Milestone Value', category: 'Milestone', accessor: (_p, m) => m?.hasPayment ? m.paymentAmount : '--' },

        // Use unique unused parameter names to avoid "Duplicate identifier" errors
        { id: 'issue_title', label: language === 'ar' ? 'عنوان المشكلة' : 'Issue Title', category: 'Issue', accessor: (_p, _m, i) => i?.title || '--' },
        { id: 'issue_status', label: language === 'ar' ? 'حالة المشكلة' : 'Issue Status', category: 'Issue', accessor: (_p, _m, i) => i?.status || '--' },
        { id: 'issue_priority', label: language === 'ar' ? 'الأولوية' : 'Priority', category: 'Issue', accessor: (_p, _m, i) => i?.priority || '--' },
        { id: 'issue_assignee', label: language === 'ar' ? 'المسؤول عن الحل' : 'Assigned Agent', category: 'Issue', accessor: (_p, _m, i) => i?.assignee?.name || '--' },

        // Use unique unused parameter names to avoid "Duplicate identifier" errors
        { id: 'user_name', label: language === 'ar' ? 'اسم الموظف' : 'User Name', category: 'User', accessor: (_p, _m, _i, u) => u?.name || '--' },
        { id: 'user_role', label: language === 'ar' ? 'الدور الوظيفي' : 'Role', category: 'User', accessor: (_p, _m, _i, u) => u?.type || '--' },

        { 
            id: 'team_name', 
            label: language === 'ar' ? 'الفريق' : 'Team', 
            category: 'Milestone', 
            accessor: (p, m) => {
                const teamId = m?.teamId || p?.teamId;
                return teams.find(t => t.id === teamId)?.name || '--';
            }
        },
        { id: 'proj_country', label: language === 'ar' ? 'الدولة' : 'Country', category: 'Project', accessor: (p) => p?.country?.name || '--' },
    ], [teams, language]);

    const filteredAvailableFields = AVAILABLE_FIELDS.filter(f => 
        !selectedFields.find(sf => sf.id === f.id) && 
        f.label.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleAddField = (field: Field) => {
        if (!selectedFields.find(f => f.id === field.id)) {
            setSelectedFields([...selectedFields, field]);
        }
    };

    const removeField = (fieldId: string) => {
        setSelectedFields(selectedFields.filter(f => f.id !== fieldId));
    };

    const reportData = useMemo(() => {
        const categories = new Set(selectedFields.map(f => f.category));

        if (!isAggregationMode) {
            let rows: any[] = [];

            // تحديد الكيان الأساسي للتقرير بناءً على الأولويات: Issue > Milestone > Project > User
            if (categories.has('Issue')) {
                issues.forEach(i => {
                    const row: any = {};
                    const proj = projects.find(p => p.id === i.projectId);
                    const user = users.find(u => u.id === i.assigneeId);
                    selectedFields.forEach(f => { row[f.id] = f.accessor(proj, undefined, i, user); });
                    rows.push(row);
                });
            } else if (categories.has('Milestone')) {
                milestones.forEach(m => {
                    const row: any = {};
                    const proj = projects.find(p => p.id === m.projectId);
                    selectedFields.forEach(f => { row[f.id] = f.accessor(proj, m, undefined, undefined); });
                    rows.push(row);
                });
            } else if (categories.has('Project')) {
                projects.forEach(p => {
                    const row: any = {};
                    const user = users.find(u => u.id === p.projectManagerId);
                    selectedFields.forEach(f => { row[f.id] = f.accessor(p, undefined, undefined, user); });
                    rows.push(row);
                });
            } else if (categories.has('User')) {
                users.forEach(u => {
                    const row: any = {};
                    selectedFields.forEach(f => { row[f.id] = f.accessor(undefined, undefined, undefined, u); });
                    rows.push(row);
                });
            }

            return rows.filter(row => {
                return Object.entries(rowFilters).every(([fieldId, filterValue]) => {
                    const val = filterValue as string;
                    if (!val) return true;
                    return String(row[fieldId] || '').toLowerCase().includes(val.toLowerCase());
                });
            });
        } else {
            // وضع الإحصائيات (Aggregation)
            const groupingField = AVAILABLE_FIELDS.find(f => f.id === groupByFieldId);
            if (!groupingField) return [];

            const aggMap = new Map<string, { label: string, count: number, sum: number }>();

            // التجميع قد يكون حسب المشروع، العميل، أو الموظف (كمدير مشروع)
            projects.forEach(p => {
                const label = String(groupingField.accessor(p, undefined, undefined, users.find(u => u.id === p.projectManagerId)) || '--');
                if (!aggMap.has(label)) aggMap.set(label, { label, count: 0, sum: 0 });

                const entry = aggMap.get(label)!;
                const pMilestones = milestones.filter(m => m.projectId === p.id);

                entry.count += pMilestones.length;
                entry.sum += pMilestones.reduce((s, m) => s + (m.hasPayment ? m.paymentAmount : 0), 0);
            });

            return Array.from(aggMap.values()).map(i => {
                const avg = i.count > 0 ? i.sum / i.count : 0;
                return {
                    [groupByFieldId]: i.label, 
                    'agg_count': i.count, 
                    'agg_sum': i.sum,
                    'agg_avg': avg,
                    'agg_sum_fmt': i.sum.toLocaleString(),
                    'agg_avg_fmt': avg.toLocaleString(undefined, { maximumFractionDigits: 2 })
                };
            }).sort((a, b) => {
                const key = `agg_${aggMeasure}`;
                return (b[key as keyof typeof b] as number) - (a[key as keyof typeof a] as number);
            });
        }
    }, [projects, milestones, issues, users, selectedFields, rowFilters, isAggregationMode, groupByFieldId, AVAILABLE_FIELDS, aggMeasure]);

    const displayColumns = useMemo(() => {
        if (!isAggregationMode) return selectedFields;
        const gField = AVAILABLE_FIELDS.find(f => f.id === groupByFieldId)!;
        return [
            gField, 
            { id: 'agg_count', label: t.metric_count }, 
            { id: 'agg_sum_fmt', label: t.totalValue }, 
            { id: 'agg_avg_fmt', label: t.avgValue }
        ] as any[];
    }, [isAggregationMode, selectedFields, groupByFieldId, AVAILABLE_FIELDS, t]);

    const graphMax = useMemo(() => {
        if (!isAggregationMode || reportData.length === 0) return 1;
        const key = `agg_${aggMeasure}`;
        return Math.max(...reportData.map(d => Number(d[key as keyof typeof d])), 1);
    }, [isAggregationMode, reportData, aggMeasure]);

    const formatGraphValue = (val: number) => {
        if (aggMeasure === 'count') return val.toString();
        return '$' + val.toLocaleString(undefined, { maximumFractionDigits: 0 });
    };

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-10">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{t.subtitle}</p>
                </div>
                <div className="flex items-center gap-2">
                    <div className="bg-slate-100 dark:bg-slate-800 p-1 rounded-xl flex gap-1">
                        <button onClick={() => setIsAggregationMode(false)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${!isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.detailedMode}</button>
                        <button onClick={() => setIsAggregationMode(true)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.aggMode}</button>
                    </div>
                    <button onClick={() => {}} className="px-6 py-2.5 bg-violet-600 text-white text-[9px] font-black uppercase tracking-widest rounded-xl hover:bg-violet-700 shadow-lg shadow-violet-500/20">{t.export}</button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                <div className="lg:col-span-3 space-y-4">
                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[650px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800">
                             <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">{t.availableFields}</h2>
                             <div className="relative">
                                <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder={t.searchPlaceholder} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl p-2.5 text-xs outline-none focus:ring-1 focus:ring-violet-500" />
                                <svg className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-2">
                            <div className="pb-4">
                                <h3 className="text-[8px] font-black text-violet-500 uppercase tracking-widest mb-3 ps-1">{t.projectSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'Project').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-violet-300 dark:hover:border-violet-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-violet-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="pb-4">
                                <h3 className="text-[8px] font-black text-blue-500 uppercase tracking-widest mb-3 ps-1">{t.milestoneSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'Milestone').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-blue-300 dark:hover:border-blue-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="pb-4">
                                <h3 className="text-[8px] font-black text-red-500 uppercase tracking-widest mb-3 ps-1">{t.issueSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'Issue').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-red-300 dark:hover:border-red-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <h3 className="text-[8px] font-black text-emerald-500 uppercase tracking-widest mb-3 ps-1">{t.userSource}</h3>
                                <div className="space-y-1.5">
                                    {filteredAvailableFields.filter(f => f.category === 'User').map(field => (
                                        <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-emerald-300 dark:hover:border-emerald-700 transition-all flex items-center justify-between group">
                                            <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                            <span className="text-emerald-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-9 space-y-6">
                    {isAggregationMode && reportData.length > 0 && (
                        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] shadow-sm animate-in fade-in slide-in-from-top-4">
                            <div className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4">
                                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.chartTitle}</h2>
                                <div className="flex gap-2 bg-slate-50 dark:bg-slate-800 p-1 rounded-xl">
                                    <button onClick={() => setAggMeasure('count')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'count' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_count}</button>
                                    <button onClick={() => setAggMeasure('sum')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'sum' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_sum}</button>
                                    <button onClick={() => setAggMeasure('avg')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'avg' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_avg}</button>
                                </div>
                            </div>

                            <div className="h-56 flex items-end gap-3 px-2">
                                {reportData.slice(0, 15).map((row, idx) => {
                                    const valKey = `agg_${aggMeasure}`;
                                    const val = Number(row[valKey as keyof typeof row]);
                                    const pct = (val / graphMax) * 100;
                                    return (
                                        <div key={idx} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                                            <div className="absolute bottom-full mb-2 bg-slate-800 text-white text-[9px] font-black px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none whitespace-nowrap">
                                                {row[groupByFieldId]}: {formatGraphValue(val)}
                                            </div>
                                            <div 
                                                style={{ height: `${Math.max(pct, 2)}%` }} 
                                                className="w-full max-w-[40px] bg-gradient-to-t from-violet-600 to-indigo-400 rounded-t-xl hover:from-violet-500 hover:to-indigo-300 transition-all duration-500 shadow-lg shadow-violet-500/10"
                                            ></div>
                                            <span className="mt-3 text-[7px] font-black text-slate-400 uppercase truncate w-full text-center">{row[groupByFieldId]}</span>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {!isAggregationMode && (
                        <div className="bg-slate-100/50 dark:bg-slate-900/40 border-2 border-dashed border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] min-h-[120px]">
                             <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 px-2">{t.dropZone}</h2>
                             <div className="flex flex-wrap gap-2">
                                {selectedFields.length === 0 ? (
                                    <div className="w-full text-center py-4 opacity-20 italic text-xs font-black uppercase tracking-widest">{t.dropHint}</div>
                                ) : selectedFields.map(field => (
                                    <div key={field.id} className="bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 px-4 py-2 rounded-xl shadow-sm flex items-center gap-3 animate-in zoom-in-95">
                                        <span className={`w-1.5 h-1.5 rounded-full ${field.category === 'Project' ? 'bg-violet-500' : field.category === 'Milestone' ? 'bg-blue-500' : field.category === 'Issue' ? 'bg-red-500' : 'bg-emerald-500'}`}></span>
                                        <span className="text-[10px] font-black text-slate-700 dark:text-slate-200">{field.label}</span>
                                        <button onClick={() => removeField(field.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                                            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                                        </button>
                                    </div>
                                ))}
                             </div>
                        </div>
                    )}

                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[500px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center bg-slate-50/30 dark:bg-slate-800/20">
                            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{t.preview}</h2>
                            <div className="flex items-center gap-4">
                                {isAggregationMode && (
                                    <div className="flex items-center gap-4">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[9px] font-black text-slate-400 uppercase">{t.groupBy}</span>
                                            <select value={groupByFieldId} onChange={e => setGroupByFieldId(e.target.value)} className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-1.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-violet-500 transition-all">
                                                {AVAILABLE_FIELDS.filter(f => f.category === 'Project' || f.category === 'User').map(f => <option key={f.id} value={f.id}>{f.label}</option>)}
                                            </select>
                                        </div>
                                    </div>
                                )}
                                <span className="text-[10px] font-black text-violet-600 bg-violet-50 dark:bg-violet-900/30 px-3 py-1 rounded-full uppercase">{reportData.length} {t.rowsCount}</span>
                            </div>
                        </div>
                        <div className="flex-1 overflow-auto custom-scrollbar">
                            <table className="w-full text-start border-collapse">
                                <thead className="sticky top-0 bg-white dark:bg-slate-900 z-10">
                                    <tr className="bg-slate-50 dark:bg-slate-800/50">
                                        {displayColumns.map(f => (
                                            <th key={f.id} className="px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-start whitespace-nowrap border-b border-slate-100 dark:border-slate-800">
                                                {f.label}
                                                {!isAggregationMode && (
                                                    <input type="text" value={rowFilters[f.id] || ''} onChange={e => setRowFilters(v => ({...v, [f.id]: (e.target as HTMLInputElement).value}))} placeholder={t.filterPlaceholder} className="block mt-2 w-full bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-md p-1.5 text-[8px] font-bold outline-none" />
                                                )}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                    {reportData.length > 0 ? reportData.map((row, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-colors">
                                            {displayColumns.map(f => (
                                                <td key={f.id} className={`px-5 py-3.5 text-[10px] font-bold whitespace-nowrap ${f.id.startsWith('agg_') ? 'text-violet-600 dark:text-violet-400' : 'text-slate-600 dark:text-slate-300'}`}>
                                                    {row[f.id as keyof typeof row]}
                                                </td>
                                            ))}
                                        </tr>
                                    )) : (
                                        <tr>
                                            <td colSpan={displayColumns.length} className="px-6 py-20 text-center text-[10px] font-black text-slate-200 uppercase tracking-[0.4em]">{t.noResults}</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const translations = {
    ar: {
        title: "بناء التقارير المخصصة", subtitle: "صمم تقاريرك الخاصة بسحب وإفلات الحقول المطلوبة.", availableFields: "قائمة الحقول", dropZone: "أعمدة التقرير المختارة", dropHint: "انقر على الحقول لإضافتها كأعمدة للتقرير", preview: "المعاينة المباشرة", export: "تصدير CSV", searchPlaceholder: "ابحث عن حقل...", clear: "تفريغ", noFields: "لم يتم اختيار أعمدة بعد.", filterPlaceholder: "تصفية...", noResults: "لا توجد بيانات مطابقة.", rowsCount: "سجل", detailedMode: "عرض تفصيلي", aggMode: "وضع الإحصائيات", groupBy: "تجميع حسب:", measureBy: "عرض المقياس:", metric_count: "العدد (Count)", metric_sum: "المجموع (Sum)", metric_avg: "المتوسط (Avg)", projectSource: "مشروع", milestoneSource: "معلم/دفعة", issueSource: "الأعطال (Issues)", userSource: "الموظفون", chartTitle: "التمثيل البياني للإحصائيات", valueLabel: "القيمة", totalValue: "إجمالي القيمة", avgValue: "متوسط القيمة"
    },
    en: {
        title: "Custom Report Builder", subtitle: "Design your custom reports by selecting fields.", availableFields: "Field Library", dropZone: "Selected Columns", dropHint: "Click fields from the library to add them to your report", preview: "Live Preview", export: "Export CSV", searchPlaceholder: "Search fields...", clear: "Clear", noFields: "No columns selected.", filterPlaceholder: "Filter...", noResults: "No results found.", rowsCount: "Rows", detailedMode: "Detailed View", aggMode: "Analytics Mode", groupBy: "Group By:", measureBy: "Measure:", metric_count: "Count", metric_sum: "Sum", metric_avg: "Average", projectSource: "Project", milestoneSource: "Milestone", issueSource: "Issues", userSource: "Users", chartTitle: "Analytics Visualization", valueLabel: "Value", totalValue: "Total Value", avgValue: "Avg Value"
    }
};

export default ReportsBuilder;

import React, { useState, useMemo } from 'react';
import { Project, Milestone, Language, Lookup, Issue, User } from '../types';

interface Field {
    id: string;
    label: string;
    category: 'Project' | 'Milestone' | 'Issue' | 'User';
    accessor: (proj?: Project, mile?: Milestone, issue?: Issue, user?: User) => string | number | null;
}

interface ReportsBuilderProps {
    projects: Project[];
    milestones: Milestone[];
    issues: Issue[];
    users: User[];
    teams: Lookup[];
    language: Language;
}

type AggMeasure = 'count' | 'sum' | 'avg';

const ReportsBuilder: React.FC<ReportsBuilderProps> = ({ projects, milestones, issues, users, teams, language }) => {
    const [selectedFields, setSelectedFields] = useState<Field[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [rowFilters, setRowFilters] = useState<Record<string, string>>({});
    const [isAggregationMode, setIsAggregationMode] = useState(false);
    const [groupByFieldId, setGroupByFieldId] = useState<string>('proj_customer');
    const [aggMeasure, setAggMeasure] = useState<AggMeasure>('count');

    const t = translations[language];

    const AVAILABLE_FIELDS: Field[] = useMemo(() => [
        { id: 'proj_name', label: language === 'ar' ? 'اسم المشروع' : 'Project Name', category: 'Project', accessor: (p) => p?.name || '--' },
        { id: 'proj_code', label: language === 'ar' ? 'كود المشروع' : 'Project Code', category: 'Project', accessor: (p) => p?.projectCode || '--' },
        { id: 'proj_pm', label: language === 'ar' ? 'مدير المشروع' : 'Project Manager', category: 'Project', accessor: (p) => p?.projectManager?.name || '--' },
        { id: 'proj_customer', label: language === 'ar' ? 'العميل' : 'Customer', category: 'Project', accessor: (p) => p?.customer?.name || '--' },
        { id: 'proj_status', label: language === 'ar' ? 'حالة المشروع' : 'Project Status', category: 'Project', accessor: (p) => p?.status?.name || '--' },
        { id: 'proj_progress', label: language === 'ar' ? 'نسبة التقدم' : 'Progress', category: 'Project', accessor: (p) => p ? `${p.progress}%` : '--' },

        { id: 'mile_title', label: language === 'ar' ? 'عنوان المعلم' : 'Milestone Title', category: 'Milestone', accessor: (_p, m) => m?.title || '--' },
        { id: 'mile_status', label: language === 'ar' ? 'حالة المعلم' : 'Milestone Status', category: 'Milestone', accessor: (_p, m) => m?.status || '--' },
        { id: 'mile_amount', label: language === 'ar' ? 'قيمة الدفعة' : 'Milestone Value', category: 'Milestone', accessor: (_p, m) => m?.hasPayment ? m.paymentAmount : 0 },

        { id: 'issue_title', label: language === 'ar' ? 'عنوان المشكلة' : 'Issue Title', category: 'Issue', accessor: (_p, _m, i) => i?.title || '--' },
        { id: 'issue_status', label: language === 'ar' ? 'حالة المشكلة' : 'Issue Status', category: 'Issue', accessor: (_p, _m, i) => i?.status || '--' },
        { id: 'issue_priority', label: language === 'ar' ? 'الأولوية' : 'Priority', category: 'Issue', accessor: (_p, _m, i) => i?.priority || '--' },
        { id: 'issue_assignee', label: language === 'ar' ? 'المسؤول عن الحل' : 'Assigned Agent', category: 'Issue', accessor: (_p, _m, i) => i?.assignee?.name || '--' },

        { id: 'user_name', label: language === 'ar' ? 'اسم الموظف' : 'User Name', category: 'User', accessor: (_p, _m, _i, u) => u?.name || '--' },
        { id: 'user_role', label: language === 'ar' ? 'الدور الوظيفي' : 'Role', category: 'User', accessor: (_p, _m, _i, u) => u?.type || '--' },

        { 
            id: 'team_name', 
            label: language === 'ar' ? 'الفريق' : 'Team', 
            category: 'Milestone', 
            accessor: (p, m) => {
                const teamId = m?.teamId || p?.teamId;
                return teams.find(t => t.id === teamId)?.name || '--';
            }
        },
        { id: 'proj_country', label: language === 'ar' ? 'الدولة' : 'Country', category: 'Project', accessor: (p) => p?.country?.name || '--' },
    ], [teams, language]);

    const handleAddField = (field: Field) => {
        if (!selectedFields.find(f => f.id === field.id)) {
            setSelectedFields([...selectedFields, field]);
        }
    };

    const removeField = (fieldId: string) => {
        setSelectedFields(selectedFields.filter(f => f.id !== fieldId));
    };

    // المحرك الموحد للبيانات
    const processedReport = useMemo(() => {
        if (selectedFields.length === 0) return { detailedRows: [], aggRows: [] };

        const categories = new Set(selectedFields.map(f => f.category));
        let baseRows: any[] = [];

        // 1. توليد الصفوف التفصيلية بناءً على المصدر الأكثر تخصيصاً
        if (categories.has('Issue')) {
            issues.forEach(i => {
                const row: any = {};
                const proj = projects.find(p => p.id === i.projectId);
                const user = users.find(u => u.id === i.assigneeId);
                const mile = milestones.find(m => m.id === i.milestoneId);
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(proj, mile, i, user); });
                baseRows.push(row);
            });
        } else if (categories.has('Milestone')) {
            milestones.forEach(m => {
                const row: any = {};
                const proj = projects.find(p => p.id === m.projectId);
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(proj, m, undefined, undefined); });
                baseRows.push(row);
            });
        } else if (categories.has('Project')) {
            projects.forEach(p => {
                const row: any = {};
                const user = users.find(u => u.id === p.projectManagerId);
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(p, undefined, undefined, user); });
                baseRows.push(row);
            });
        } else if (categories.has('User')) {
            users.forEach(u => {
                const row: any = {};
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(undefined, undefined, undefined, u); });
                baseRows.push(row);
            });
        }

        // 2. تطبيق فلاتر الأعمدة (Row Filters)
        const filteredDetailedRows = baseRows.filter(row => {
            return Object.entries(rowFilters).every(([fieldId, filterValue]) => {
                if (!filterValue) return true;
                return String(row[fieldId] || '').toLowerCase().includes(filterValue.toLowerCase());
            });
        });

        // 3. التجميع (Aggregation) بناءً على النتائج المصفاة فقط
        const aggMap = new Map<string, { label: string, count: number, sum: number }>();

        filteredDetailedRows.forEach(row => {
            const groupValue = String(row[groupByFieldId] || t.unassigned);
            if (!aggMap.has(groupValue)) {
                aggMap.set(groupValue, { label: groupValue, count: 0, sum: 0 });
            }
            const entry = aggMap.get(groupValue)!;
            entry.count += 1;

            // محاولة العثور على قيمة مالية للجمع (مثل mile_amount)
            const numericValue = Number(row['mile_amount']) || 0;
            entry.sum += numericValue;
        });

        const aggRows = Array.from(aggMap.values()).map(item => {
            const avg = item.count > 0 ? item.sum / item.count : 0;
            return {
                [groupByFieldId]: item.label,
                'agg_count': item.count,
                'agg_sum': item.sum,
                'agg_avg': avg,
                'agg_sum_fmt': item.sum.toLocaleString(undefined, { minimumFractionDigits: 0 }),
                'agg_avg_fmt': avg.toLocaleString(undefined, { maximumFractionDigits: 2 })
            };
        }).sort((a, b) => {
            const key = `agg_${aggMeasure}`;
            return (b[key as keyof typeof b] as number) - (a[key as keyof typeof a] as number);
        });

        return { detailedRows: filteredDetailedRows, aggRows };
    }, [selectedFields, projects, milestones, issues, users, rowFilters, groupByFieldId, aggMeasure, AVAILABLE_FIELDS, t.unassigned]);

    const displayData = isAggregationMode ? processedReport.aggRows : processedReport.detailedRows;

    const displayColumns = useMemo(() => {
        if (!isAggregationMode) return selectedFields;
        const gField = AVAILABLE_FIELDS.find(f => f.id === groupByFieldId) || { id: groupByFieldId, label: t.groupBy };
        return [
            gField, 
            { id: 'agg_count', label: t.metric_count }, 
            { id: 'agg_sum_fmt', label: t.totalValue }, 
            { id: 'agg_avg_fmt', label: t.avgValue }
        ] as any[];
    }, [isAggregationMode, selectedFields, groupByFieldId, AVAILABLE_FIELDS, t]);

    const graphMax = useMemo(() => {
        if (!isAggregationMode || processedReport.aggRows.length === 0) return 1;
        const key = `agg_${aggMeasure}`;
        return Math.max(...processedReport.aggRows.map(d => Number(d[key as keyof typeof d])), 1);
    }, [isAggregationMode, processedReport.aggRows, aggMeasure]);

    const formatGraphValue = (val: number) => {
        if (aggMeasure === 'count') return val.toString();
        return '$' + val.toLocaleString(undefined, { maximumFractionDigits: 0 });
    };

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-10">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{t.subtitle}</p>
                </div>
                <div className="flex items-center gap-2">
                    <div className="bg-slate-100 dark:bg-slate-800 p-1 rounded-xl flex gap-1">
                        <button onClick={() => setIsAggregationMode(false)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${!isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.detailedMode}</button>
                        <button onClick={() => setIsAggregationMode(true)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.aggMode}</button>
                    </div>
                    <button onClick={() => {}} className="px-6 py-2.5 bg-violet-600 text-white text-[9px] font-black uppercase tracking-widest rounded-xl hover:bg-violet-700 shadow-lg shadow-violet-500/20">{t.export}</button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                <div className="lg:col-span-3 space-y-4">
                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[650px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800">
                             <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">{t.availableFields}</h2>
                             <div className="relative">
                                <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder={t.searchPlaceholder} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl p-2.5 text-xs outline-none focus:ring-1 focus:ring-violet-500" />
                                <svg className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-2">
                             {['Project', 'Milestone', 'Issue', 'User'].map(cat => (
                                <div key={cat} className="pb-4">
                                    <h3 className={`text-[8px] font-black uppercase tracking-widest mb-3 ps-1 ${cat === 'Project' ? 'text-violet-500' : cat === 'Milestone' ? 'text-blue-500' : cat === 'Issue' ? 'text-red-500' : 'text-emerald-500'}`}>{cat} Source</h3>
                                    <div className="space-y-1.5">
                                        {AVAILABLE_FIELDS.filter(f => f.category === cat && f.label.toLowerCase().includes(searchTerm.toLowerCase())).map(field => (
                                            <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-violet-300 dark:hover:border-violet-700 transition-all flex items-center justify-between group">
                                                <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                                <span className="text-violet-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                            </button>
                                        ))}
                                    </div>
                                </div>
                             ))}
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-9 space-y-6">
                    {isAggregationMode && processedReport.aggRows.length > 0 && (
                        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] shadow-sm animate-in fade-in slide-in-from-top-4">
                            <div className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4">
                                <div className="flex flex-col">
                                    <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.chartTitle}</h2>
                                    <p className="text-[9px] font-bold text-violet-500 uppercase">Aggregating {processedReport.detailedRows.length} filtered records</p>
                                </div>
                                <div className="flex gap-2 bg-slate-50 dark:bg-slate-800 p-1 rounded-xl">
                                    <button onClick={() => setAggMeasure('count')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'count' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_count}</button>
                                    <button onClick={() => setAggMeasure('sum')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'sum' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_sum}</button>
                                    <button onClick={() => setAggMeasure('avg')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'avg' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_avg}</button>
                                </div>
                            </div>

                            <div className="h-56 flex items-end gap-3 px-2">
                                {processedReport.aggRows.slice(0, 15).map((row, idx) => {
                                    const valKey = `agg_${aggMeasure}`;
                                    const val = Number(row[valKey as keyof typeof row]);
                                    const pct = (val / graphMax) * 100;
                                    return (
                                        <div key={idx} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                                            <div className="absolute bottom-full mb-2 bg-slate-800 text-white text-[9px] font-black px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none whitespace-nowrap">
                                                {row[groupByFieldId]}: {formatGraphValue(val)}
                                            </div>
                                            <div 
                                                style={{ height: `${Math.max(pct, 2)}%` }} 
                                                className="w-full max-w-[40px] bg-gradient-to-t from-violet-600 to-indigo-400 rounded-t-xl hover:from-violet-500 hover:to-indigo-300 transition-all duration-500 shadow-lg shadow-violet-500/10"
                                            ></div>
                                            <span className="mt-3 text-[7px] font-black text-slate-400 uppercase truncate w-full text-center">{row[groupByFieldId]}</span>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {!isAggregationMode && (
                        <div className="bg-slate-100/50 dark:bg-slate-900/40 border-2 border-dashed border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] min-h-[120px]">
                             <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 px-2">{t.dropZone}</h2>
                             <div className="flex flex-wrap gap-2">
                                {selectedFields.length === 0 ? (
                                    <div className="w-full text-center py-4 opacity-20 italic text-xs font-black uppercase tracking-widest">{t.dropHint}</div>
                                ) : selectedFields.map(field => (
                                    <div key={field.id} className="bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 px-4 py-2 rounded-xl shadow-sm flex items-center gap-3 animate-in zoom-in-95">
                                        <span className={`w-1.5 h-1.5 rounded-full ${field.category === 'Project' ? 'bg-violet-500' : field.category === 'Milestone' ? 'bg-blue-500' : field.category === 'Issue' ? 'bg-red-500' : 'bg-emerald-500'}`}></span>
                                        <span className="text-[10px] font-black text-slate-700 dark:text-slate-200">{field.label}</span>
                                        <button onClick={() => removeField(field.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                                            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                                        </button>
                                    </div>
                                ))}
                             </div>
                        </div>
                    )}

                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[500px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center bg-slate-50/30 dark:bg-slate-800/20">
                            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{isAggregationMode ? t.aggMode : t.preview}</h2>
                            <div className="flex items-center gap-4">
                                {isAggregationMode && (
                                    <div className="flex items-center gap-2">
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{t.groupBy}</span>
                                        <select value={groupByFieldId} onChange={e => setGroupByFieldId(e.target.value)} className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-1.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-violet-500 transition-all">
                                            {selectedFields.map(f => <option key={f.id} value={f.id}>{f.label}</option>)}
                                        </select>
                                    </div>
                                )}
                                <span className="text-[10px] font-black text-violet-600 bg-violet-50 dark:bg-violet-900/30 px-3 py-1 rounded-full uppercase">{displayData.length} {t.rowsCount}</span>
                            </div>
                        </div>
                        <div className="flex-1 overflow-auto custom-scrollbar">
                            <table className="w-full text-start border-collapse">
                                <thead className="sticky top-0 bg-white dark:bg-slate-900 z-10">
                                    <tr className="bg-slate-50 dark:bg-slate-800/50">
                                        {displayColumns.map(f => (
                                            <th key={f.id} className="px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-start whitespace-nowrap border-b border-slate-100 dark:border-slate-800">
                                                {f.label}
                                                {!isAggregationMode && (
                                                    <input type="text" value={rowFilters[f.id] || ''} onChange={e => setRowFilters(v => ({...v, [f.id]: (e.target as HTMLInputElement).value}))} placeholder={t.filterPlaceholder} className="block mt-2 w-full bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-md p-1.5 text-[8px] font-bold outline-none" />
                                                )}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                    {displayData.length > 0 ? displayData.map((row, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-colors">
                                            {displayColumns.map(f => (
                                                <td key={f.id} className={`px-5 py-3.5 text-[10px] font-bold whitespace-nowrap ${f.id.startsWith('agg_') ? 'text-violet-600 dark:text-violet-400' : 'text-slate-600 dark:text-slate-300'}`}>
                                                    {f.id === 'agg_sum_fmt' || f.id === 'agg_avg_fmt' ? `$${row[f.id as keyof typeof row]}` : row[f.id as keyof typeof row]}
                                                </td>
                                            ))}
                                        </tr>
                                    )) : (
                                        <tr>
                                            <td colSpan={displayColumns.length} className="px-6 py-20 text-center text-[10px] font-black text-slate-200 uppercase tracking-[0.4em]">{t.noResults}</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const translations = {
    ar: {
        title: "بناء التقارير المخصصة", subtitle: "صمم تقاريرك الخاصة بسحب وإفلات الحقول المطلوبة.", availableFields: "قائمة الحقول", dropZone: "أعمدة التقرير المختارة", dropHint: "انقر على الحقول لإضافتها كأعمدة للتقرير", preview: "المعاينة المباشرة", export: "تصدير CSV", searchPlaceholder: "ابحث عن حقل...", clear: "تفريغ", noFields: "لم يتم اختيار أعمدة بعد.", filterPlaceholder: "تصفية...", noResults: "لا توجد بيانات مطابقة.", rowsCount: "سجل", detailedMode: "عرض تفصيلي", aggMode: "وضع الإحصائيات", groupBy: "تجميع حسب:", measureBy: "عرض المقياس:", metric_count: "العدد (Count)", metric_sum: "المجموع (Sum)", metric_avg: "المتوسط (Avg)", chartTitle: "التمثيل البياني للإحصائيات", totalValue: "إجمالي القيمة", avgValue: "متوسط القيمة", unassigned: "غير معين"
    },
    en: {
        title: "Custom Report Builder", subtitle: "Design your custom reports by selecting fields.", availableFields: "Field Library", dropZone: "Selected Columns", dropHint: "Click fields from the library to add them to your report", preview: "Live Preview", export: "Export CSV", searchPlaceholder: "Search fields...", clear: "Clear", noFields: "No columns selected.", filterPlaceholder: "Filter...", noResults: "No results found.", rowsCount: "Rows", detailedMode: "Detailed View", aggMode: "Analytics Mode", groupBy: "Group By:", measureBy: "Measure:", metric_count: "Count", metric_sum: "Sum", metric_avg: "Average", chartTitle: "Analytics Visualization", totalValue: "Total Value", avgValue: "Avg Value", unassigned: "Unassigned"
    }
};

export default ReportsBuilder;

import React, { useState, useMemo } from 'react';
import { Project, Milestone, Language, Lookup, Issue, User } from '../types';

interface Field {
    id: string;
    label: string;
    category: 'Project' | 'Milestone' | 'Issue' | 'User';
    accessor: (proj?: Project, mile?: Milestone, issue?: Issue, user?: User) => string | number | null;
}

interface ReportsBuilderProps {
    projects: Project[];
    milestones: Milestone[];
    issues: Issue[];
    users: User[];
    teams: Lookup[];
    language: Language;
}

type AggMeasure = 'count' | 'sum' | 'avg';

const ReportsBuilder: React.FC<ReportsBuilderProps> = ({ projects, milestones, issues, users, teams, language }) => {
    const [selectedFields, setSelectedFields] = useState<Field[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [rowFilters, setRowFilters] = useState<Record<string, string>>({});
    const [isAggregationMode, setIsAggregationMode] = useState(false);
    const [groupByFieldId, setGroupByFieldId] = useState<string>('proj_customer');
    const [aggMeasure, setAggMeasure] = useState<AggMeasure>('count');

    const t = translations[language];

    const AVAILABLE_FIELDS: Field[] = useMemo(() => [
        { id: 'proj_name', label: language === 'ar' ? 'اسم المشروع' : 'Project Name', category: 'Project', accessor: (p) => p?.name || '--' },
        { id: 'proj_code', label: language === 'ar' ? 'كود المشروع' : 'Project Code', category: 'Project', accessor: (p) => p?.projectCode || '--' },
        { id: 'proj_pm', label: language === 'ar' ? 'مدير المشروع' : 'Project Manager', category: 'Project', accessor: (p) => p?.projectManager?.name || '--' },
        { id: 'proj_customer', label: language === 'ar' ? 'العميل' : 'Customer', category: 'Project', accessor: (p) => p?.customer?.name || '--' },
        { id: 'proj_status', label: language === 'ar' ? 'حالة المشروع' : 'Project Status', category: 'Project', accessor: (p) => p?.status?.name || '--' },
        { id: 'proj_progress', label: language === 'ar' ? 'نسبة التقدم' : 'Progress', category: 'Project', accessor: (p) => p ? `${p.progress}%` : '--' },

        { id: 'mile_title', label: language === 'ar' ? 'عنوان المعلم' : 'Milestone Title', category: 'Milestone', accessor: (_p, m) => m?.title || '--' },
        { id: 'mile_status', label: language === 'ar' ? 'حالة المعلم' : 'Milestone Status', category: 'Milestone', accessor: (_p, m) => m?.status || '--' },
        { id: 'mile_amount', label: language === 'ar' ? 'قيمة الدفعة' : 'Milestone Value', category: 'Milestone', accessor: (_p, m) => m?.hasPayment ? m.paymentAmount : 0 },

        { id: 'issue_title', label: language === 'ar' ? 'عنوان المشكلة' : 'Issue Title', category: 'Issue', accessor: (_p, _m, i) => i?.title || '--' },
        { id: 'issue_status', label: language === 'ar' ? 'حالة المشكلة' : 'Issue Status', category: 'Issue', accessor: (_p, _m, i) => i?.status || '--' },
        { id: 'issue_priority', label: language === 'ar' ? 'الأولوية' : 'Priority', category: 'Issue', accessor: (_p, _m, i) => i?.priority || '--' },
        { id: 'issue_assignee', label: language === 'ar' ? 'المسؤول عن الحل' : 'Assigned Agent', category: 'Issue', accessor: (_p, _m, i) => i?.assignee?.name || '--' },

        { id: 'user_name', label: language === 'ar' ? 'اسم الموظف' : 'User Name', category: 'User', accessor: (_p, _m, _i, u) => u?.name || '--' },
        { id: 'user_role', label: language === 'ar' ? 'الدور الوظيفي' : 'Role', category: 'User', accessor: (_p, _m, _i, u) => u?.type || '--' },

        { 
            id: 'team_name', 
            label: language === 'ar' ? 'الفريق' : 'Team', 
            category: 'Milestone', 
            accessor: (p, m) => {
                const teamId = m?.teamId || p?.teamId;
                return teams.find(t => t.id === teamId)?.name || '--';
            }
        },
        { id: 'proj_country', label: language === 'ar' ? 'الدولة' : 'Country', category: 'Project', accessor: (p) => p?.country?.name || '--' },
    ], [teams, language]);

    const handleAddField = (field: Field) => {
        if (!selectedFields.find(f => f.id === field.id)) {
            setSelectedFields([...selectedFields, field]);
        }
    };

    const removeField = (fieldId: string) => {
        setSelectedFields(selectedFields.filter(f => f.id !== fieldId));
    };

    // المحرك الموحد للبيانات
    const processedReport = useMemo(() => {
        if (selectedFields.length === 0) return { detailedRows: [], aggRows: [] };

        const categories = new Set(selectedFields.map(f => f.category));
        let baseRows: any[] = [];

        // 1. توليد الصفوف التفصيلية بناءً على المصدر الأكثر تخصيصاً
        if (categories.has('Issue')) {
            issues.forEach(i => {
                const row: any = {};
                const proj = projects.find(p => p.id === i.projectId);
                const user = users.find(u => u.id === i.assigneeId);
                const mile = milestones.find(m => m.id === i.milestoneId);
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(proj, mile, i, user); });
                baseRows.push(row);
            });
        } else if (categories.has('Milestone')) {
            milestones.forEach(m => {
                const row: any = {};
                const proj = projects.find(p => p.id === m.projectId);
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(proj, m, undefined, undefined); });
                baseRows.push(row);
            });
        } else if (categories.has('Project')) {
            projects.forEach(p => {
                const row: any = {};
                const user = users.find(u => u.id === p.projectManagerId);
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(p, undefined, undefined, user); });
                baseRows.push(row);
            });
        } else if (categories.has('User')) {
            users.forEach(u => {
                const row: any = {};
                AVAILABLE_FIELDS.forEach(f => { row[f.id] = f.accessor(undefined, undefined, undefined, u); });
                baseRows.push(row);
            });
        }

        // 2. تطبيق فلاتر الأعمدة (Row Filters)
        const filteredDetailedRows = baseRows.filter(row => {
            return Object.entries(rowFilters).every(([fieldId, filterValue]) => {
                if (!filterValue) return true;
                // Fixed: Ensure filterValue is treated as a string to avoid 'property toLowerCase does not exist on type unknown' error.
                return String(row[fieldId] || '').toLowerCase().includes(String(filterValue).toLowerCase());
            });
        });

        // 3. التجميع (Aggregation) بناءً على النتائج المصفاة فقط
        const aggMap = new Map<string, { label: string, count: number, sum: number }>();

        filteredDetailedRows.forEach(row => {
            const groupValue = String(row[groupByFieldId] || t.unassigned);
            if (!aggMap.has(groupValue)) {
                aggMap.set(groupValue, { label: groupValue, count: 0, sum: 0 });
            }
            const entry = aggMap.get(groupValue)!;
            entry.count += 1;

            // محاولة العثور على قيمة مالية للجمع (مثل mile_amount)
            const numericValue = Number(row['mile_amount']) || 0;
            entry.sum += numericValue;
        });

        const aggRows = Array.from(aggMap.values()).map(item => {
            const avg = item.count > 0 ? item.sum / item.count : 0;
            return {
                [groupByFieldId]: item.label,
                'agg_count': item.count,
                'agg_sum': item.sum,
                'agg_avg': avg,
                'agg_sum_fmt': item.sum.toLocaleString(undefined, { minimumFractionDigits: 0 }),
                'agg_avg_fmt': avg.toLocaleString(undefined, { maximumFractionDigits: 2 })
            };
        }).sort((a, b) => {
            const key = `agg_${aggMeasure}`;
            return (b[key as keyof typeof b] as number) - (a[key as keyof typeof a] as number);
        });

        return { detailedRows: filteredDetailedRows, aggRows };
    }, [selectedFields, projects, milestones, issues, users, rowFilters, groupByFieldId, aggMeasure, AVAILABLE_FIELDS, t.unassigned]);

    const displayData = isAggregationMode ? processedReport.aggRows : processedReport.detailedRows;

    const displayColumns = useMemo(() => {
        if (!isAggregationMode) return selectedFields;
        const gField = AVAILABLE_FIELDS.find(f => f.id === groupByFieldId) || { id: groupByFieldId, label: t.groupBy };
        return [
            gField, 
            { id: 'agg_count', label: t.metric_count }, 
            { id: 'agg_sum_fmt', label: t.totalValue }, 
            { id: 'agg_avg_fmt', label: t.avgValue }
        ] as any[];
    }, [isAggregationMode, selectedFields, groupByFieldId, AVAILABLE_FIELDS, t]);

    const graphMax = useMemo(() => {
        if (!isAggregationMode || processedReport.aggRows.length === 0) return 1;
        const key = `agg_${aggMeasure}`;
        return Math.max(...processedReport.aggRows.map(d => Number(d[key as keyof typeof d])), 1);
    }, [isAggregationMode, processedReport.aggRows, aggMeasure]);

    const formatGraphValue = (val: number) => {
        if (aggMeasure === 'count') return val.toString();
        return '$' + val.toLocaleString(undefined, { maximumFractionDigits: 0 });
    };

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-10">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{t.subtitle}</p>
                </div>
                <div className="flex items-center gap-2">
                    <div className="bg-slate-100 dark:bg-slate-800 p-1 rounded-xl flex gap-1">
                        <button onClick={() => setIsAggregationMode(false)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${!isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.detailedMode}</button>
                        <button onClick={() => setIsAggregationMode(true)} className={`px-4 py-1.5 text-[9px] font-black uppercase rounded-lg transition-all ${isAggregationMode ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.aggMode}</button>
                    </div>
                    <button onClick={() => {}} className="px-6 py-2.5 bg-violet-600 text-white text-[9px] font-black uppercase tracking-widest rounded-xl hover:bg-violet-700 shadow-lg shadow-violet-500/20">{t.export}</button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                <div className="lg:col-span-3 space-y-4">
                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[650px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800">
                             <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">{t.availableFields}</h2>
                             <div className="relative">
                                <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder={t.searchPlaceholder} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl p-2.5 text-xs outline-none focus:ring-1 focus:ring-violet-500" />
                                <svg className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-2">
                             {['Project', 'Milestone', 'Issue', 'User'].map(cat => (
                                <div key={cat} className="pb-4">
                                    <h3 className={`text-[8px] font-black uppercase tracking-widest mb-3 ps-1 ${cat === 'Project' ? 'text-violet-500' : cat === 'Milestone' ? 'text-blue-500' : cat === 'Issue' ? 'text-red-500' : 'text-emerald-500'}`}>{cat} Source</h3>
                                    <div className="space-y-1.5">
                                        {AVAILABLE_FIELDS.filter(f => f.category === cat && f.label.toLowerCase().includes(searchTerm.toLowerCase())).map(field => (
                                            <button key={field.id} onClick={() => handleAddField(field)} className="w-full text-start p-3 bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-violet-300 dark:hover:border-violet-700 transition-all flex items-center justify-between group">
                                                <span className="text-[10px] font-bold text-slate-700 dark:text-slate-200">{field.label}</span>
                                                <span className="text-violet-400 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg></span>
                                            </button>
                                        ))}
                                    </div>
                                </div>
                             ))}
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-9 space-y-6">
                    {isAggregationMode && processedReport.aggRows.length > 0 && (
                        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] shadow-sm animate-in fade-in slide-in-from-top-4">
                            <div className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4">
                                <div className="flex flex-col">
                                    <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.chartTitle}</h2>
                                    <p className="text-[9px] font-bold text-violet-500 uppercase">Aggregating {processedReport.detailedRows.length} filtered records</p>
                                </div>
                                <div className="flex gap-2 bg-slate-50 dark:bg-slate-800 p-1 rounded-xl">
                                    <button onClick={() => setAggMeasure('count')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'count' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_count}</button>
                                    <button onClick={() => setAggMeasure('sum')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'sum' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_sum}</button>
                                    <button onClick={() => setAggMeasure('avg')} className={`px-4 py-1.5 text-[8px] font-black uppercase rounded-lg transition-all ${aggMeasure === 'avg' ? 'bg-white dark:bg-slate-700 text-violet-600 shadow-sm' : 'text-slate-400'}`}>{t.metric_avg}</button>
                                </div>
                            </div>

                            <div className="h-56 flex items-end gap-3 px-2">
                                {processedReport.aggRows.slice(0, 15).map((row, idx) => {
                                    const valKey = `agg_${aggMeasure}`;
                                    const val = Number(row[valKey as keyof typeof row]);
                                    const pct = (val / graphMax) * 100;
                                    return (
                                        <div key={idx} className="flex-1 flex flex-col items-center justify-end h-full group relative">
                                            <div className="absolute bottom-full mb-2 bg-slate-800 text-white text-[9px] font-black px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none whitespace-nowrap">
                                                {row[groupByFieldId]}: {formatGraphValue(val)}
                                            </div>
                                            <div 
                                                style={{ height: `${Math.max(pct, 2)}%` }} 
                                                className="w-full max-w-[40px] bg-gradient-to-t from-violet-600 to-indigo-400 rounded-t-xl hover:from-violet-500 hover:to-indigo-300 transition-all duration-500 shadow-lg shadow-violet-500/10"
                                            ></div>
                                            <span className="mt-3 text-[7px] font-black text-slate-400 uppercase truncate w-full text-center">{row[groupByFieldId]}</span>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {!isAggregationMode && (
                        <div className="bg-slate-100/50 dark:bg-slate-900/40 border-2 border-dashed border-slate-200 dark:border-slate-800 p-6 rounded-[2rem] min-h-[120px]">
                             <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 px-2">{t.dropZone}</h2>
                             <div className="flex flex-wrap gap-2">
                                {selectedFields.length === 0 ? (
                                    <div className="w-full text-center py-4 opacity-20 italic text-xs font-black uppercase tracking-widest">{t.dropHint}</div>
                                ) : selectedFields.map(field => (
                                    <div key={field.id} className="bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 px-4 py-2 rounded-xl shadow-sm flex items-center gap-3 animate-in zoom-in-95">
                                        <span className={`w-1.5 h-1.5 rounded-full ${field.category === 'Project' ? 'bg-violet-500' : field.category === 'Milestone' ? 'bg-blue-500' : field.category === 'Issue' ? 'bg-red-500' : 'bg-emerald-500'}`}></span>
                                        <span className="text-[10px] font-black text-slate-700 dark:text-slate-200">{field.label}</span>
                                        <button onClick={() => removeField(field.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                                            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                                        </button>
                                    </div>
                                ))}
                             </div>
                        </div>
                    )}

                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm overflow-hidden flex flex-col h-[500px]">
                        <div className="p-5 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center bg-slate-50/30 dark:bg-slate-800/20">
                            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{isAggregationMode ? t.aggMode : t.preview}</h2>
                            <div className="flex items-center gap-4">
                                {isAggregationMode && (
                                    <div className="flex items-center gap-2">
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{t.groupBy}</span>
                                        <select value={groupByFieldId} onChange={e => setGroupByFieldId(e.target.value)} className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-1.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-violet-500 transition-all">
                                            {selectedFields.map(f => <option key={f.id} value={f.id}>{f.label}</option>)}
                                        </select>
                                    </div>
                                )}
                                <span className="text-[10px] font-black text-violet-600 bg-violet-50 dark:bg-violet-900/30 px-3 py-1 rounded-full uppercase">{displayData.length} {t.rowsCount}</span>
                            </div>
                        </div>
                        <div className="flex-1 overflow-auto custom-scrollbar">
                            <table className="w-full text-start border-collapse">
                                <thead className="sticky top-0 bg-white dark:bg-slate-900 z-10">
                                    <tr className="bg-slate-50 dark:bg-slate-800/50">
                                        {displayColumns.map(f => (
                                            <th key={f.id} className="px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-start whitespace-nowrap border-b border-slate-100 dark:border-slate-800">
                                                {f.label}
                                                {!isAggregationMode && (
                                                    <input type="text" value={rowFilters[f.id] || ''} onChange={e => setRowFilters(v => ({...v, [f.id]: (e.target as HTMLInputElement).value}))} placeholder={t.filterPlaceholder} className="block mt-2 w-full bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-md p-1.5 text-[8px] font-bold outline-none" />
                                                )}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                    {displayData.length > 0 ? displayData.map((row, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-colors">
                                            {displayColumns.map(f => (
                                                <td key={f.id} className={`px-5 py-3.5 text-[10px] font-bold whitespace-nowrap ${f.id.startsWith('agg_') ? 'text-violet-600 dark:text-violet-400' : 'text-slate-600 dark:text-slate-300'}`}>
                                                    {f.id === 'agg_sum_fmt' || f.id === 'agg_avg_fmt' ? `$${row[f.id as keyof typeof row]}` : row[f.id as keyof typeof row]}
                                                </td>
                                            ))}
                                        </tr>
                                    )) : (
                                        <tr>
                                            <td colSpan={displayColumns.length} className="px-6 py-20 text-center text-[10px] font-black text-slate-200 uppercase tracking-[0.4em]">{t.noResults}</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const translations = {
    ar: {
        title: "بناء التقارير المخصصة", subtitle: "صمم تقاريرك الخاصة بسحب وإفلات الحقول المطلوبة.", availableFields: "قائمة الحقول", dropZone: "أعمدة التقرير المختارة", dropHint: "انقر على الحقول لإضافتها كأعمدة للتقرير", preview: "المعاينة المباشرة", export: "تصدير CSV", searchPlaceholder: "ابحث عن حقل...", clear: "تفريغ", noFields: "لم يتم اختيار أعمدة بعد.", filterPlaceholder: "تصفية...", noResults: "لا توجد بيانات مطابقة.", rowsCount: "سجل", detailedMode: "عرض تفصيلي", aggMode: "وضع الإحصائيات", groupBy: "تجميع حسب:", measureBy: "عرض المقياس:", metric_count: "العدد (Count)", metric_sum: "المجموع (Sum)", metric_avg: "المتوسط (Avg)", chartTitle: "التمثيل البياني للإحصائيات", totalValue: "إجمالي القيمة", avgValue: "متوسط القيمة", unassigned: "غير معين"
    },
    en: {
        title: "Custom Report Builder", subtitle: "Design your custom reports by selecting fields.", availableFields: "Field Library", dropZone: "Selected Columns", dropHint: "Click fields from the library to add them to your report", preview: "Live Preview", export: "Export CSV", searchPlaceholder: "Search fields...", clear: "Clear", noFields: "No columns selected.", filterPlaceholder: "Filter...", noResults: "No results found.", rowsCount: "Rows", detailedMode: "Detailed View", aggMode: "Analytics Mode", groupBy: "Group By:", measureBy: "Measure:", metric_count: "Count", metric_sum: "Sum", metric_avg: "Average", chartTitle: "Analytics Visualization", totalValue: "Total Value", avgValue: "Avg Value", unassigned: "Unassigned"
    }
};

export default ReportsBuilder;

import React, { useMemo, useState } from 'react';
import { Project, Milestone, Lookup, Language, User, PaymentStatus, MilestoneStatus, Issue } from '../types';
import SearchableSelect from './SearchableSelect';

interface KPIDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    issues: Issue[];
    allUsers: User[];
    teams: Lookup[];
    projectManagers: User[];
    customers: Lookup[];
    countries: Lookup[];
    language: Language;
}

const KPIDashboard: React.FC<KPIDashboardProps> = ({ projects, milestones, issues, allUsers, projectManagers, language }) => {
    const t = translations[language];

    // States for Filters
    const [projectSearch, setProjectSearch] = useState('');
    const [selectedManager, setSelectedManager] = useState('all');
    const [selectedMonthYear, setSelectedMonthYear] = useState('all');

    // States for UI Expansion
    const [expandedManagers, setExpandedManagers] = useState<Record<string, boolean>>({});
    const [expandedProjects, setExpandedProjects] = useState<Record<string, boolean>>({});

    // 1. توليد خيارات الشهر/السنة مرتبة تصاعدياً
    const monthYearOptions = useMemo(() => {
        const uniqueMonthYears = new Set<string>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
                uniqueMonthYears.add(key);
            }
        });

        const sortedKeys = Array.from(uniqueMonthYears).sort((a, b) => a.localeCompare(b));

        return [
            { value: 'all', label: t.allTime },
            ...sortedKeys.map(key => {
                const [year, month] = key.split('-').map(Number);
                const label = new Date(year, month - 1).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long', year: 'numeric' });
                return { value: key, label };
            })
        ];
    }, [milestones, language, t.allTime]);

    // 2. تصفية البيانات بناءً على الفترة الزمنية المختارة
    const filteredMilestones = useMemo(() => {
        return milestones.filter(m => {
            const periodMatch = selectedMonthYear === 'all' || (m.dueDate && `${new Date(m.dueDate).getFullYear()}-${String(new Date(m.dueDate).getMonth() + 1).padStart(2, '0')}` === selectedMonthYear);
            return periodMatch;
        });
    }, [milestones, selectedMonthYear]);

    const filteredIssues = useMemo(() => {
        return issues.filter(i => {
            if (selectedMonthYear === 'all') return true;
            const date = new Date(i.createdAt);
            const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
            return key === selectedMonthYear;
        });
    }, [issues, selectedMonthYear]);

    // 3. تجميع البيانات حسب (المدير -> المشروع -> المعالم)
    const groupedHierarchy = useMemo(() => {
        const hierarchy: Record<string, { manager: User | undefined, projects: Record<string, { project: Project, milestones: Milestone[] }> }> = {};

        const eligibleProjects = projects.filter(p => {
            const nameMatch = p.name.toLowerCase().includes(projectSearch.toLowerCase()) || 
                             p.projectCode.toLowerCase().includes(projectSearch.toLowerCase());
            const managerMatch = selectedManager === 'all' || p.projectManagerId === selectedManager;
            return nameMatch && managerMatch;
        });

        const eligibleProjectIds = new Set(eligibleProjects.map(p => p.id));

        filteredMilestones.forEach(m => {
            if (!eligibleProjectIds.has(m.projectId)) return;

            const project = projects.find(p => p.id === m.projectId);
            if (!project) return;

            const managerId = project.projectManagerId || 'unassigned';
            const manager = projectManagers.find(u => u.id === managerId);

            if (!hierarchy[managerId]) {
                hierarchy[managerId] = { manager, projects: {} };
            }

            if (!hierarchy[managerId].projects[project.id]) {
                hierarchy[managerId].projects[project.id] = { project, milestones: [] };
            }

            hierarchy[managerId].projects[project.id].milestones.push(m);
        });

        return hierarchy;
    }, [projects, filteredMilestones, projectManagers, projectSearch, selectedManager]);

    // 4. إحصائيات الأعطال (Issues)
    const issueStats = useMemo(() => {
        const byProject: Record<string, { name: string, count: number }> = {};
        const byUser: Record<string, { name: string, count: number, avatar?: string }> = {};

        filteredIssues.forEach(issue => {
            // حسب المشروع
            if (issue.projectId) {
                const proj = projects.find(p => p.id === issue.projectId);
                const projName = proj?.name || t.unknownProject;
                if (!byProject[issue.projectId]) byProject[issue.projectId] = { name: projName, count: 0 };
                byProject[issue.projectId].count++;
            }

            // حسب المستخدم (Assignee)
            if (issue.assigneeId) {
                const user = allUsers.find(u => u.id === issue.assigneeId);
                const userName = user?.name || t.unassigned;
                if (!byUser[issue.assigneeId]) byUser[issue.assigneeId] = { name: userName, count: 0, avatar: user?.avatarUrl };
                byUser[issue.assigneeId].count++;
            }
        });

        return {
            byProject: Object.values(byProject).sort((a, b) => b.count - a.count).slice(0, 5),
            byUser: Object.values(byUser).sort((a, b) => b.count - a.count).slice(0, 5)
        };
    }, [filteredIssues, projects, allUsers, t]);

    // 5. إحصائيات المؤشرات الرئيسية (KPIs)
    const kpis = useMemo(() => {
        const projectIdsInHierarchy = new Set(Object.values(groupedHierarchy).flatMap((m: any) => Object.keys(m.projects)));
        const milestonesInHierarchy = Object.values(groupedHierarchy).flatMap((m: any) => Object.values(m.projects).flatMap((p: any) => p.milestones));

        const totalValue = milestonesInHierarchy.reduce((sum, m) => sum + (m.paymentAmount || 0), 0);
        const collected = milestonesInHierarchy
            .filter(m => m.paymentStatus === PaymentStatus.Paid)
            .reduce((sum, m) => sum + (m.paymentAmount || 0), 0);

        const avgProgress = projectIdsInHierarchy.size > 0 
            ? Math.round(projects.filter(p => projectIdsInHierarchy.has(p.id)).reduce((sum, p) => sum + (p.progress || 0), 0) / projectIdsInHierarchy.size)
            : 0;

        return {
            totalValue,
            collected,
            pending: totalValue - collected,
            avgProgress,
            count: projectIdsInHierarchy.size,
            totalIssues: filteredIssues.length
        };
    }, [groupedHierarchy, projects, filteredIssues]);

    const toggleManagerExpansion = (managerId: string) => {
        setExpandedManagers(prev => ({ ...prev, [managerId]: !prev[managerId] }));
    };

    const toggleProjectExpansion = (projectId: string) => {
        setExpandedProjects(prev => ({ ...prev, [projectId]: !prev[projectId] }));
    };

    const formatCurrency = (val: number) => 
        val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    const statusColors = {
        [MilestoneStatus.Completed]: 'text-emerald-500 bg-emerald-500/10',
        [MilestoneStatus.InProgress]: 'text-indigo-500 bg-indigo-500/10',
        [MilestoneStatus.Pending]: 'text-orange-500 bg-orange-500/10',
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            {/* Fixed: Added z-50 to the container to ensure dropdowns stack correctly */}
            <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border border-slate-100 dark:border-slate-800 p-6 rounded-[2.5rem] shadow-sm flex flex-wrap items-center gap-4 relative z-[60]">
                <div className="flex-1 min-w-[240px] relative">
                    <span className="absolute inset-y-0 left-4 rtl:left-auto rtl:right-4 flex items-center pointer-events-none text-slate-400">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </span>
                    <input 
                        type="text" 
                        value={projectSearch}
                        onChange={(e) => setProjectSearch(e.target.value)}
                        placeholder={t.searchByProject}
                        className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl py-3 pl-12 pr-4 rtl:pr-12 rtl:pl-4 text-sm font-bold focus:ring-2 focus:ring-indigo-500 shadow-inner"
                    />
                </div>
                <div className="w-60 min-w-[200px]">
                    <SearchableSelect options={[{ value: 'all', label: t.allManagers }, ...projectManagers.map(m => ({ value: m.id, label: m.name }))]} value={selectedManager} onChange={setSelectedManager} placeholder={t.projectManager} language={language} />
                </div>
                {/* Fixed: Increased width of Month/Year dropdown to prevent "206" clipping */}
                <div className="w-72 min-w-[240px]">
                    <SearchableSelect options={monthYearOptions} value={selectedMonthYear} onChange={setSelectedMonthYear} placeholder={t.period} language={language} />
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-8 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden group">
                    <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:scale-150 transition-transform"></div>
                    <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-2">{t.totalAmount}</p>
                    <p className="text-3xl font-black">{formatCurrency(kpis.totalValue)}</p>
                    <div className="mt-4 pt-4 border-t border-white/10 flex justify-between items-center text-[10px] font-bold">
                        <span>{kpis.count} {t.projects}</span>
                        <span className="bg-white/20 px-2 py-1 rounded-lg uppercase">{selectedMonthYear === 'all' ? 'All Time' : 'Period View'}</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm group">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.collected}</p>
                    <p className="text-3xl font-black text-emerald-500">{formatCurrency(kpis.collected)}</p>
                    <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full mt-6 overflow-hidden">
                        <div className="bg-emerald-500 h-full rounded-full transition-all duration-1000" style={{ width: `${(kpis.collected/kpis.totalValue)*100 || 0}%` }}></div>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.pending}</p>
                    <p className="text-3xl font-black text-orange-500">{formatCurrency(kpis.pending)}</p>
                    <div className="flex items-center gap-1.5 mt-4">
                        <span className="w-1.5 h-1.5 rounded-full bg-orange-500"></span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase">Remaining Balance</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm relative overflow-hidden group">
                    <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                        <svg className="w-16 h-16" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    </div>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.activeIssues}</p>
                    <p className="text-3xl font-black text-red-500">{kpis.totalIssues}</p>
                    <div className="mt-4 pt-4 border-t border-slate-50 dark:border-slate-800">
                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter italic">Requires Attention</span>
                    </div>
                </div>
            </div>

            {/* Tree View Roadmap Section */}
            <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                <div className="flex justify-between items-end mb-10">
                    <div>
                        <h3 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.timelineRoadmap}</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{t.roadmapSubtitle}</p>
                    </div>
                    <div className="text-[10px] font-black text-violet-600 bg-violet-50 dark:bg-violet-900/20 px-4 py-2 rounded-xl">
                        {selectedMonthYear === 'all' ? t.allTime : monthYearOptions.find(o => o.value === selectedMonthYear)?.label}
                    </div>
                </div>

                <div className="space-y-6">
                    {Object.keys(groupedHierarchy).length > 0 ? (Object.entries(groupedHierarchy) as [string, any][]).map(([managerId, mGroup]) => {
                        const isMgrExpanded = !!expandedManagers[managerId];
                        const projectList = Object.values(mGroup.projects);

                        return (
                            <div key={managerId} className="space-y-3">
                                <div onClick={() => toggleManagerExpansion(managerId)} className={`p-4 rounded-3xl flex items-center justify-between cursor-pointer transition-all border-2 ${isMgrExpanded ? 'bg-indigo-50/50 border-indigo-200 dark:bg-indigo-900/10 dark:border-indigo-800' : 'bg-white dark:bg-slate-900 border-transparent hover:border-slate-100 dark:hover:border-slate-800'}`}>
                                    <div className="flex items-center gap-4">
                                        <div className="relative">
                                            <img src={mGroup.manager?.avatarUrl || `https://ui-avatars.com/api/?name=${mGroup.manager?.name || '?'}&background=6366f1&color=fff`} className="w-12 h-12 rounded-2xl border-2 border-white dark:border-slate-800 shadow-sm" alt={mGroup.manager?.name} />
                                            <span className="absolute -bottom-1 -right-1 w-5 h-5 bg-indigo-600 text-white text-[8px] font-black rounded-full flex items-center justify-center border-2 border-white dark:border-[#0f172a]">{projectList.length}</span>
                                        </div>
                                        <div>
                                            <h4 className="font-black text-slate-800 dark:text-white uppercase text-sm tracking-tight">{mGroup.manager?.name || t.unassigned}</h4>
                                            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest">{t.projectManager}</p>
                                        </div>
                                    </div>
                                    <svg className={`w-5 h-5 text-indigo-400 transition-transform duration-300 ${isMgrExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 9l-7 7-7-7" /></svg>
                                </div>

                                {isMgrExpanded && (
                                    <div className="ps-8 space-y-3 animate-in slide-in-from-top-2 duration-300">
                                        {projectList.map(({ project, milestones: pMilestones }: any) => {
                                            const isPrjExpanded = !!expandedProjects[project.id];
                                            return (
                                                <div key={project.id} className="border border-slate-100 dark:border-slate-800 rounded-3xl overflow-hidden transition-all duration-300 shadow-sm">
                                                    <div onClick={() => toggleProjectExpansion(project.id)} className={`p-5 flex items-center justify-between cursor-pointer transition-colors ${isPrjExpanded ? 'bg-slate-50 dark:bg-slate-800/50' : 'bg-white dark:bg-slate-900 hover:bg-slate-50'}`}>
                                                        <div className="flex items-center gap-5 min-w-0">
                                                            <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${isPrjExpanded ? 'bg-violet-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                                                                <svg className={`w-4 h-4 transition-transform duration-300 ${isPrjExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 9l-7 7-7-7" /></svg>
                                                            </div>
                                                            <div className="min-w-0">
                                                                <h4 className="font-black text-slate-800 dark:text-white truncate text-xs">{project.name}</h4>
                                                                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{project.projectCode}</span>
                                                            </div>
                                                        </div>
                                                        <div className="flex items-center gap-6">
                                                            <div className="hidden sm:block text-right">
                                                                <p className="text-[9px] font-black text-slate-400 uppercase">{t.progress}</p>
                                                                <p className="text-xs font-black text-indigo-600">{project.progress}%</p>
                                                            </div>
                                                            <div className="text-right min-w-[60px]">
                                                                <p className="text-[9px] font-black text-slate-400 uppercase">{t.items}</p>
                                                                <p className="text-xs font-black text-slate-800 dark:text-white">{pMilestones.length}</p>
                                                            </div>
                                                        </div>
                                                    </div>

                                                    {isPrjExpanded && (
                                                        <div className="p-4 bg-white dark:bg-slate-950 border-t border-slate-50 dark:border-slate-800 animate-in slide-in-from-top-2 duration-300">
                                                            <div className="space-y-2 ps-10 relative">
                                                                <div className="absolute left-5 rtl:left-auto rtl:right-5 top-0 bottom-6 w-0.5 bg-slate-100 dark:bg-slate-800"></div>
                                                                {pMilestones.map((m: any) => (
                                                                    <div key={m.id} className="group flex items-center justify-between p-4 bg-slate-50/50 dark:bg-slate-900/30 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800 transition-all border border-transparent hover:border-slate-100 dark:hover:border-slate-800">
                                                                        <div className="flex items-center gap-4 min-w-0">
                                                                            <div className="w-2 h-2 rounded-full bg-violet-400 shrink-0 group-hover:scale-125 transition-transform"></div>
                                                                            <div className="min-w-0">
                                                                                <p className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate">{m.title}</p>
                                                                                <div className="flex items-center gap-3 mt-1">
                                                                                    <span className={`text-[8px] font-black px-2 py-0.5 rounded-md uppercase ${statusColors[m.status as MilestoneStatus]}`}>{t[m.status as MilestoneStatus]}</span>
                                                                                    {m.dueDate && <span className="text-[9px] font-bold text-slate-400">{new Date(m.dueDate).toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short' })}</span>}
                                                                                </div>
                                                                            </div>
                                                                        </div>
                                                                        {m.hasPayment && (
                                                                            <div className="text-right">
                                                                                <p className="text-xs font-black text-emerald-600">{formatCurrency(m.paymentAmount)}</p>
                                                                                <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">{t[m.paymentStatus as PaymentStatus || 'Pending']}</p>
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        );
                    }) : (
                        <div className="py-20 text-center text-[10px] font-black text-slate-300 uppercase tracking-[0.5em]">{t.noData}</div>
                    )}
                </div>
            </div>

            {/* Issue Analysis Section */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Issues by Project */}
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex items-center gap-3 mb-8">
                        <div className="w-10 h-10 bg-red-500/10 rounded-2xl flex items-center justify-center text-red-500">
                             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                        </div>
                        <div>
                            <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-widest">{t.issuesByProject}</h3>
                            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{t.criticalAreas}</p>
                        </div>
                    </div>
                    <div className="space-y-4">
                        {issueStats.byProject.length > 0 ? issueStats.byProject.map((item, idx) => (
                            <div key={idx} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/30 rounded-2xl group hover:bg-red-50 dark:hover:bg-red-900/10 transition-all border border-transparent hover:border-red-100 dark:hover:border-red-800">
                                <span className="text-xs font-black text-slate-700 dark:text-slate-200 truncate pr-4 rtl:pr-0 rtl:pl-4">{item.name}</span>
                                <div className="flex items-center gap-2">
                                    <span className="text-xs font-black text-red-500">{item.count}</span>
                                    <span className="text-[9px] font-black text-slate-400 uppercase">{t.issuesCount}</span>
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-10 text-[10px] font-black text-slate-300 uppercase italic">{t.noIssuesFound}</div>
                        )}
                    </div>
                </div>

                {/* Issues by User */}
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex items-center gap-3 mb-8">
                        <div className="w-10 h-10 bg-indigo-500/10 rounded-2xl flex items-center justify-center text-indigo-500">
