                    <span className={`absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full border-2 border-white dark:border-slate-800 ${issue.status === IssueStatus.Closed ? 'bg-slate-300' : 'bg-green-500 animate-pulse'}`}></span>
