);

const IssueDetailModal: React.FC<{ issue: Issue, onClose: () => void, language: Language, currentUser?: User, onUpdateStatus: (s: IssueStatus) => Promise<void>, onAddComment: (c: string) => Promise<void> }> = ({ issue, onClose, language, currentUser, onUpdateStatus, onAddComment }) => {
    const t = translations[language];
    const [comment, setComment] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    const isAssignee = currentUser?.id === issue.assigneeId;

    useEffect(() => {
        const handleEsc = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
        window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [onClose]);

    const handleAddComment = async () => {
        if (!comment.trim() || isSaving) return;
        setIsSaving(true);
        try {
            await onAddComment(comment);
            setComment('');
        } catch (e) {
            console.error("Failed to add comment");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div 
            className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl flex items-center justify-center z-[200] p-4 animate-in fade-in duration-300"
            onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
        >
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[3rem] shadow-2xl w-full max-w-6xl overflow-hidden animate-in zoom-in-95 flex flex-col md:flex-row h-[85vh] relative" dir={language === 'ar' ? 'rtl' : 'ltr'}>

                {/* Information Side */}
                <div className="flex-1 flex flex-col h-full border-e border-slate-100 dark:border-slate-800 overflow-hidden">
                    <div className="p-8 pb-4 flex justify-between items-start">
                        <div className="space-y-1">
                            <span className="px-3 py-1 bg-violet-100 text-violet-700 text-[10px] font-black rounded-lg uppercase tracking-widest">{issue.project?.name}</span>
                            <h2 className="text-3xl font-black text-slate-800 dark:text-white leading-tight mt-3">{issue.title}</h2>
                        </div>
                        <button onClick={onClose} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-red-500 rounded-full transition-all group shadow-sm flex items-center gap-2">
                             <span className="text-[10px] font-black uppercase tracking-widest group-hover:block hidden">{t.close}</span>
                             <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12"/></svg>
                        </button>
                    </div>

                    <div className="flex-1 overflow-y-auto custom-scrollbar p-8 pt-2">
                        <div className="bg-slate-50 dark:bg-slate-800/40 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800 mb-8">
                             <p className="text-xs font-black text-slate-400 uppercase mb-4 tracking-widest">{t.description}</p>
                             <p className="text-sm text-slate-600 dark:text-slate-300 whitespace-pre-wrap leading-relaxed">{issue.description}</p>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div className="p-5 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-[2rem] shadow-sm">
                                <p className="text-[10px] font-black text-slate-400 uppercase mb-3 ps-1">{t.status}</p>
                                <select 
                                    value={issue.status} 
                                    disabled={!isAssignee}
                                    onChange={(e) => onUpdateStatus(e.target.value as IssueStatus)}
                                    className="w-full p-3 bg-slate-50 dark:bg-slate-900 border-none rounded-2xl text-xs font-bold focus:ring-2 focus:ring-violet-500 transition-all outline-none disabled:opacity-50"
                                >
                                    {Object.values(IssueStatus).map(s => <option key={s} value={s}>{s}</option>)}
                                </select>
                            </div>
                            <div className="p-5 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-[2rem] shadow-sm">
                                <p className="text-[10px] font-black text-slate-400 uppercase mb-3 ps-1">{t.assignedTo}</p>
                                <div className="flex items-center gap-4 p-1">
                                    <img src={issue.assignee?.avatarUrl || `https://ui-avatars.com/api/?name=${issue.assignee?.name || '?'}&background=8b5cf6&color=fff`} className="w-10 h-10 rounded-full border-2 border-violet-100" />
                                    <div>
                                        <span className="text-xs font-black text-slate-800 dark:text-white block">{issue.assignee?.name}</span>
                                        <span className="text-[9px] font-black text-violet-500 uppercase">{issue.assignee?.type || 'Staff'}</span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="mt-8 pt-8 border-t border-slate-50 dark:border-slate-800 grid grid-cols-2 gap-4">
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase mb-1">{t.reportedAt}</p>
                                <p className="text-xs font-bold text-slate-700 dark:text-slate-300">{new Date(issue.createdAt).toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US', { dateStyle: 'full' })}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase mb-1">{t.priority}</p>
                                <p className="text-xs font-bold text-slate-700 dark:text-slate-300">{issue.priority}</p>
                            </div>
                        </div>
                    </div>

                    <div className="p-6 border-t border-slate-50 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 flex justify-end">
                        <button onClick={onClose} className="px-10 py-3 bg-slate-900 text-white dark:bg-white dark:text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-transform shadow-xl">
                            {t.close}
                        </button>
                    </div>
                </div>

                {/* Conversation Side */}
                <div className="w-full md:w-[450px] bg-slate-50 dark:bg-slate-900/50 flex flex-col h-full border-s border-slate-100 dark:border-slate-800">
                    <div className="p-6 border-b border-white dark:border-slate-800 flex justify-between items-center bg-white/30 dark:bg-slate-900/30">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-violet-100 dark:bg-violet-900/30 rounded-xl text-violet-600">
                                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M17 8h2a2 2 0 012 2v6a2 2 0 01-2 2h-2v4l-4-4H9a1.994 1.994.586m0 0L11 14h4a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2v4l.586-.586z" /></svg>
                            </div>
                            <h3 className="text-xs font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{t.comments}</h3>
                        </div>
                        <span className="text-[10px] font-black text-white bg-violet-600 px-2.5 py-1 rounded-full shadow-lg shadow-violet-500/30">{(issue.comments || []).length}</span>
                    </div>

                    <div className="flex-1 p-6 overflow-y-auto custom-scrollbar space-y-8 bg-gradient-to-b from-transparent to-slate-100/50 dark:to-slate-950/20">
                        {(issue.comments || []).length > 0 ? issue.comments?.map((c, idx) => {
                            const isMe = c.userId === currentUser?.id;
                            return (
                                <div key={c.id} className={`flex gap-4 animate-in slide-in-from-bottom-2 duration-300`} style={{ animationDelay: `${idx * 50}ms` }}>
                                    <img src={c.user?.avatarUrl || `https://ui-avatars.com/api/?name=${c.user?.name || '?'}&background=a78bfa&color=fff`} className="w-10 h-10 rounded-2xl shadow-sm mt-1 shrink-0 border-2 border-white dark:border-slate-800" />
                                    <div className="flex-1 space-y-2">
                                        <div className="flex items-center justify-between">
                                            <span className={`text-[11px] font-black ${isMe ? 'text-violet-600' : 'text-slate-700 dark:text-slate-200'}`}>{isMe ? t.you : c.user?.name}</span>
                                            <span className="text-[9px] font-black text-slate-400 uppercase">{new Date(c.createdAt).toLocaleTimeString(language === 'ar' ? 'ar-EG' : 'en-US', { hour: '2-digit', minute: '2-digit' })}</span>
                                        </div>
                                        <div className={`p-4 rounded-[1.5rem] text-sm leading-relaxed shadow-sm ${isMe ? 'bg-violet-600 text-white rounded-tr-none rtl:rounded-tl-none rtl:rounded-tr-[1.5rem]' : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-tl-none rtl:rounded-tr-none rtl:rounded-tl-[1.5rem] border border-slate-100 dark:border-slate-700'}`}>
                                            {c.content}
                                        </div>
                                        <p className="text-[8px] font-black text-slate-400 uppercase px-1 tracking-tighter">
                                            {new Date(c.createdAt).toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short' })}
                                        </p>
                                    </div>
                                </div>
                            );
                        }) : (
                            <div className="h-full flex flex-col items-center justify-center opacity-20 italic">
                                <svg className="w-16 h-16 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="1.5"><path strokeLinecap="round" strokeLinejoin="round" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
                                <p className="text-[11px] font-black uppercase tracking-[0.3em]">{t.noComments}</p>
                            </div>
                        )}
                    </div>

                    {/* Add Comment Input */}
                    <div className="p-8 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-[0_-10px_25px_-5px_rgba(0,0,0,0.05)]">
                        {isAssignee ? (
                            <div className="space-y-4">
                                <div className="relative group">
                                    <textarea 
                                        value={comment}
                                        onChange={(e) => setComment(e.target.value)}
                                        placeholder={t.addCommentPlaceholder}
                                        className="w-full p-5 bg-slate-50 dark:bg-slate-800 rounded-[2rem] text-sm font-bold outline-none focus:ring-4 focus:ring-violet-500/10 transition-all resize-none h-28 border-2 border-transparent focus:border-violet-500 focus:bg-white dark:focus:bg-slate-900"
                                        disabled={isSaving}
                                    />
                                    <button 
                                        onClick={handleAddComment}
                                        disabled={isSaving || !comment.trim()}
                                        className="absolute bottom-4 right-4 rtl:right-auto rtl:left-4 p-4 bg-violet-600 text-white rounded-2xl hover:scale-105 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale shadow-xl shadow-violet-500/30 flex items-center gap-2 group"
                                    >
                                        {isSaving ? (
                                            <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div>
                                        ) : (
                                            <svg className="w-5 h-5 group-hover:translate-x-1 rtl:group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M13 5l7 7-7 7M5 5l7 7-7 7"/></svg>
                                        )}
                                    </button>
                                </div>
                                <p className="text-[9px] font-black text-slate-400 text-center uppercase tracking-widest">{language === 'ar' ? 'أنت المسؤول عن تنفيذ هذه المهمة' : 'You are the assignee for this task'}</p>
                            </div>
                        ) : (
                            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-800 text-center">
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-relaxed">
                                    {t.assigneeOnlyNote}
                                </p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

const AddIssueModal: React.FC<{ onClose: () => void, projects: Project[], milestones: Milestone[], users: User[], language: Language, onSave: (d: any) => Promise<void> }> = ({ onClose, projects, milestones, users, language, onSave }) => {
    const t = translations[language];
    const [formData, setFormData] = useState({ title: '', description: '', projectId: '', milestoneId: '', assigneeId: '', priority: IssuePriority.Medium, status: IssueStatus.Open });
    const [isSaving, setIsSaving] = useState(false);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);

    const filteredMilestones = useMemo(() => milestones.filter(m => m.projectId === formData.projectId), [milestones, formData.projectId]);

    const projectOptions = useMemo(() => projects.map(p => ({ value: p.id, label: p.name })), [projects]);
    const userOptions = useMemo(() => users.map(u => ({ value: u.id, label: u.name })), [users]);
    const milestoneOptions = useMemo(() => [
        { value: '', label: t.selectMilestone },
        ...filteredMilestones.map(m => ({ value: m.id, label: m.title }))
    ], [filteredMilestones, t.selectMilestone]);

    const inputClasses = "w-full p-4 bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-violet-500 dark:focus:border-violet-500 rounded-2xl text-sm font-bold outline-none transition-all";

    const handleSave = async () => {
        if (!formData.title || !formData.projectId) {
            setErrorMsg(language === 'ar' ? "يرجى ملء الحقول الإلزامية (العنوان والمشروع)" : "Title and Project are required");
            return;
        }
        setIsSaving(true);
        setErrorMsg(null);
        try {
            await onSave(formData);
        } catch (e: any) {
            setErrorMsg(e.message || "Failed to save task.");
            setIsSaving(false);
        }
    };

    return (
        <div 
            className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-[200] p-4 animate-in fade-in duration-300"
            onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
        >
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[3rem] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95" dir={language === 'ar' ? 'rtl' : 'ltr'}>
                <div className="p-10">
                    <div className="flex justify-between items-center mb-10">
                        <div>
                            <h2 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.newIssue}</h2>
                            <div className="h-1 w-12 bg-violet-600 rounded-full mt-2"></div>
                        </div>
                        <button onClick={onClose} className="p-2 bg-slate-50 dark:bg-slate-800 text-slate-400 hover:text-slate-800 rounded-full transition-all">&times;</button>
                    </div>

                    {errorMsg && (
                        <div className="mb-8 p-4 bg-red-50 dark:bg-red-900/20 border-2 border-red-100 dark:border-red-800 rounded-2xl">
                            <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{errorMsg}</p>
                        </div>
                    )}

                    <div className="space-y-6">
                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-2 tracking-widest">{t.issueTitle} *</label>
                            <input type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className={inputClasses} placeholder={t.issueTitle} disabled={isSaving} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-2 tracking-widest">{t.description}</label>
                            <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className={inputClasses + " h-28 resize-none"} disabled={isSaving} />
                        </div>
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-2 tracking-widest">{t.project} *</label>
                                <SearchableSelect 
                                    options={projectOptions} 
                                    value={formData.projectId} 
                                    onChange={val => setFormData({...formData, projectId: val, milestoneId: ''})} 
                                    placeholder={t.selectProject} 
                                    searchPlaceholder={t.allProjects}
                                    language={language}
                                />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-2 tracking-widest">{t.milestone}</label>
                                <SearchableSelect 
                                    options={milestoneOptions} 
                                    value={formData.milestoneId} 
                                    onChange={val => setFormData({...formData, milestoneId: val})} 
                                    placeholder={t.selectMilestone} 
                                    language={language}
                                />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-2 tracking-widest">{t.assignedTo}</label>
                                <SearchableSelect 
                                    options={userOptions} 
                                    value={formData.assigneeId} 
                                    onChange={val => setFormData({...formData, assigneeId: val})} 
                                    placeholder={t.selectAssignee} 
                                    searchPlaceholder={language === 'ar' ? 'ابحث عن موظف...' : 'Search for user...'}
                                    language={language}
                                />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-2 tracking-widest">{t.priority}</label>
                                <select value={formData.priority} onChange={e => setFormData({...formData, priority: e.target.value as IssuePriority})} className={inputClasses} disabled={isSaving}>
                                    {Object.values(IssuePriority).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                    </div>

                    <div className="flex justify-end gap-4 mt-12 pt-8 border-t border-slate-50 dark:border-slate-800">
                        <button onClick={onClose} className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-slate-800 transition-colors" disabled={isSaving}>{t.cancel}</button>
                        <button 
                            onClick={handleSave} 
                            disabled={isSaving}
                            className="px-12 py-4 bg-violet-600 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl hover:bg-violet-700 transition-all shadow-2xl shadow-violet-500/30 flex items-center gap-3 active:scale-95 disabled:grayscale"
                        >
                            {isSaving ? (
                                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                            ) : (
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7"/></svg>
                            )}
                            {isSaving ? (language === 'ar' ? 'جاري الحفظ...' : 'Saving...') : t.saveIssue}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

const translations = {
    ar: {
        title: "إدارة المهام والعيوب", subtitle: "تتبع المهام التقنية والعيوب وإسندها للمستخدمين.", newIssue: "إضافة مهمة", allProjects: "كل المشاريع", allStatuses: "كل الحالات", allAssignees: "كل الموظفين", project: "المشروع", milestone: "المعلم", assignedTo: "المسؤول عن التنفيذ", reportedAt: "تاريخ الإنشاء", unassigned: "غير مسند", cancel: "إلغاء", saveIssue: "حفظ المهمة", issueTitle: "عنوان المهمة", description: "وصف التفاصيل", selectProject: "اختر المشروع", selectMilestone: "اختر المعلم (اختياري)", selectAssignee: "اختر الشخص المسؤول", priority: "الأولوية", myIssues: "مهامي فقط", allIssues: "عرض كل المهام", you: "أنت (المسؤول)", noIssues: "لا توجد مهام مطابقة", status: "الحالة الحالية", comments: "ملاحظات وتحديثات التنفيذ", noComments: "لا توجد ملاحظات بعد.", addCommentPlaceholder: "أضف ملاحظة أو تحديث حول التنفيذ...", assigneeOnlyNote: "فقط الشخص المسؤول عن تنفيذ هذه المهمة يمكنه إضافة ملاحظات وتحديثات.", close: "إغلاق", gridView: "عرض البطاقات", groupedView: "عرض حسب المشروع", unknownProject: "مشروع غير معروف", issuesCount: "مهمة",
    },
    en: {
        title: "Tasks & Defects Management", subtitle: "Track technical tasks, defects and assign them to users.", newIssue: "Add Task", allProjects: "All Projects", allStatuses: "All Statuses", allAssignees: "All Assignees", project: "Project", milestone: "Milestone", assignedTo: "Assigned To", reportedAt: "Created At", unassigned: "Unassigned", cancel: "Cancel", saveIssue: "Save Task", issueTitle: "Task Title", description: "Details Description", selectProject: "Select Project", selectMilestone: "Select Milestone (Optional)", selectAssignee: "Select User", priority: "Priority", myIssues: "My Assigned Tasks", allIssues: "Show All Tasks", you: "You (Assigned)", noIssues: "No tasks found", status: "Current Status", comments: "Progress Notes & Updates", noComments: "No notes yet.", addCommentPlaceholder: "Add a note or progress update...", assigneeOnlyNote: "Only the user assigned to this task can add progress notes and updates.", close: "Close", gridView: "Grid Cards", groupedView: "Group by Project", unknownProject: "Unknown Project", issuesCount: "Tasks",
    }
};

export default Issues;

import React, { useMemo, useState } from 'react';
import { Project, Milestone, Lookup, Language, User, PaymentStatus, MilestoneStatus, Issue } from '../types';
import SearchableSelect from './SearchableSelect';

interface KPIDashboardProps {
    projects: Project[];
    milestones: Milestone[];
    issues: Issue[];
    allUsers: User[];
    teams: Lookup[];
    projectManagers: User[];
    customers: Lookup[];
    countries: Lookup[];
    language: Language;
}

const KPIDashboard: React.FC<KPIDashboardProps> = ({ projects, milestones, issues, allUsers, projectManagers, language }) => {
    const t = translations[language];

    // States for Filters
    const [projectSearch, setProjectSearch] = useState('');
    const [selectedManager, setSelectedManager] = useState('all');
    const [selectedMonthYear, setSelectedMonthYear] = useState('all');

    // States for UI Expansion
    const [expandedManagers, setExpandedManagers] = useState<Record<string, boolean>>({});
    const [expandedProjects, setExpandedProjects] = useState<Record<string, boolean>>({});

    // 1. توليد خيارات الشهر/السنة مرتبة تصاعدياً
    const monthYearOptions = useMemo(() => {
        const uniqueMonthYears = new Set<string>();
        milestones.forEach(m => {
            if (m.dueDate) {
                const date = new Date(m.dueDate);
                const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
                uniqueMonthYears.add(key);
            }
        });

        const sortedKeys = Array.from(uniqueMonthYears).sort((a, b) => a.localeCompare(b));

        return [
            { value: 'all', label: t.allTime },
            ...sortedKeys.map(key => {
                const [year, month] = key.split('-').map(Number);
                const label = new Date(year, month - 1).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long', year: 'numeric' });
                return { value: key, label };
            })
        ];
    }, [milestones, language, t.allTime]);

    // 2. تصفية البيانات بناءً على الفترة الزمنية المختارة
    const filteredMilestones = useMemo(() => {
        return milestones.filter(m => {
            const periodMatch = selectedMonthYear === 'all' || (m.dueDate && `${new Date(m.dueDate).getFullYear()}-${String(new Date(m.dueDate).getMonth() + 1).padStart(2, '0')}` === selectedMonthYear);
            return periodMatch;
        });
    }, [milestones, selectedMonthYear]);

    const filteredIssues = useMemo(() => {
        return issues.filter(i => {
            if (selectedMonthYear === 'all') return true;
            const date = new Date(i.createdAt);
            const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
            return key === selectedMonthYear;
        });
    }, [issues, selectedMonthYear]);

    // 3. تجميع البيانات حسب (المدير -> المشروع -> المعالم)
    const groupedHierarchy = useMemo(() => {
        const hierarchy: Record<string, { manager: User | undefined, projects: Record<string, { project: Project, milestones: Milestone[] }> }> = {};

        const eligibleProjects = projects.filter(p => {
            const nameMatch = p.name.toLowerCase().includes(projectSearch.toLowerCase()) || 
                             p.projectCode.toLowerCase().includes(projectSearch.toLowerCase());
            const managerMatch = selectedManager === 'all' || p.projectManagerId === selectedManager;
            return nameMatch && managerMatch;
        });

        const eligibleProjectIds = new Set(eligibleProjects.map(p => p.id));

        filteredMilestones.forEach(m => {
            if (!eligibleProjectIds.has(m.projectId)) return;

            const project = projects.find(p => p.id === m.projectId);
            if (!project) return;

            const managerId = project.projectManagerId || 'unassigned';
            const manager = projectManagers.find(u => u.id === managerId);

            if (!hierarchy[managerId]) {
                hierarchy[managerId] = { manager, projects: {} };
            }

            if (!hierarchy[managerId].projects[project.id]) {
                hierarchy[managerId].projects[project.id] = { project, milestones: [] };
            }

            hierarchy[managerId].projects[project.id].milestones.push(m);
        });

        return hierarchy;
    }, [projects, filteredMilestones, projectManagers, projectSearch, selectedManager]);

    // 4. إحصائيات المهام (Issues)
    const issueStats = useMemo(() => {
        const byProject: Record<string, { name: string, count: number }> = {};
        const byUser: Record<string, { name: string, count: number, avatar?: string }> = {};

        filteredIssues.forEach(issue => {
            if (issue.projectId) {
                const proj = projects.find(p => p.id === issue.projectId);
                const projName = proj?.name || t.unknownProject;
                if (!byProject[issue.projectId]) byProject[issue.projectId] = { name: projName, count: 0 };
                byProject[issue.projectId].count++;
            }

            if (issue.assigneeId) {
                const user = allUsers.find(u => u.id === issue.assigneeId);
                const userName = user?.name || t.unassigned;
                if (!byUser[issue.assigneeId]) byUser[issue.assigneeId] = { name: userName, count: 0, avatar: user?.avatarUrl };
                byUser[issue.assigneeId].count++;
            }
        });

        return {
            byProject: Object.values(byProject).sort((a, b) => b.count - a.count).slice(0, 5),
            byUser: Object.values(byUser).sort((a, b) => b.count - a.count).slice(0, 5)
        };
    }, [filteredIssues, projects, allUsers, t]);

    // 5. إحصائيات المؤشرات الرئيسية (KPIs)
    const kpis = useMemo(() => {
        const projectIdsInHierarchy = new Set(Object.values(groupedHierarchy).flatMap((m: any) => Object.keys(m.projects)));
        const milestonesInHierarchy = Object.values(groupedHierarchy).flatMap((m: any) => Object.values(m.projects).flatMap((p: any) => p.milestones));

        const totalValue = milestonesInHierarchy.reduce((sum, m) => sum + (m.paymentAmount || 0), 0);
        const collected = milestonesInHierarchy
            .filter(m => m.paymentStatus === PaymentStatus.Paid)
            .reduce((sum, m) => sum + (m.paymentAmount || 0), 0);

        const avgProgress = projectIdsInHierarchy.size > 0 
            ? Math.round(projects.filter(p => projectIdsInHierarchy.has(p.id)).reduce((sum, p) => sum + (p.progress || 0), 0) / projectIdsInHierarchy.size)
            : 0;

        return {
            totalValue,
            collected,
            pending: totalValue - collected,
            avgProgress,
            count: projectIdsInHierarchy.size,
            totalIssues: filteredIssues.length
        };
    }, [groupedHierarchy, projects, filteredIssues]);

    const toggleManagerExpansion = (managerId: string) => {
        setExpandedManagers(prev => ({ ...prev, [managerId]: !prev[managerId] }));
    };

    const toggleProjectExpansion = (projectId: string) => {
        setExpandedProjects(prev => ({ ...prev, [projectId]: !prev[projectId] }));
    };

    const expandAll = () => {
        const allMgrs: Record<string, boolean> = {};
        const allPrjs: Record<string, boolean> = {};
        Object.entries(groupedHierarchy).forEach(([mId, mGroup]) => {
            allMgrs[mId] = true;
            Object.keys(mGroup.projects).forEach(pId => { allPrjs[pId] = true; });
        });
        setExpandedManagers(allMgrs);
        setExpandedProjects(allPrjs);
    };

    const collapseAll = () => {
        setExpandedManagers({});
        setExpandedProjects({});
    };

    const formatCurrency = (val: number) => 
        val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    const statusColors = {
        [MilestoneStatus.Completed]: 'text-emerald-500 bg-emerald-500/10',
        [MilestoneStatus.InProgress]: 'text-indigo-500 bg-indigo-500/10',
        [MilestoneStatus.Pending]: 'text-orange-500 bg-orange-500/10',
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            {/* Filters Bar */}
            <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border border-slate-100 dark:border-slate-800 p-6 rounded-[2.5rem] shadow-sm flex flex-wrap items-center gap-4 relative z-[60]">
                <div className="flex-1 min-w-[240px] relative">
                    <span className="absolute inset-y-0 left-4 rtl:left-auto rtl:right-4 flex items-center pointer-events-none text-slate-400">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </span>
                    <input 
                        type="text" 
                        value={projectSearch}
                        onChange={(e) => setProjectSearch(e.target.value)}
                        placeholder={t.searchByProject}
                        className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl py-3 pl-12 pr-4 rtl:pr-12 rtl:pl-4 text-sm font-bold focus:ring-2 focus:ring-indigo-500 shadow-inner"
                    />
                </div>
                <div className="w-60 min-w-[200px]">
                    <SearchableSelect options={[{ value: 'all', label: t.allManagers }, ...projectManagers.map(m => ({ value: m.id, label: m.name }))]} value={selectedManager} onChange={setSelectedManager} placeholder={t.projectManager} language={language} />
                </div>
                <div className="w-72 min-w-[240px]">
                    <SearchableSelect options={monthYearOptions} value={selectedMonthYear} onChange={setSelectedMonthYear} placeholder={t.period} language={language} />
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-8 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden group">
                    <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:scale-150 transition-transform"></div>
                    <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-2">{t.totalAmount}</p>
                    <p className="text-3xl font-black">{formatCurrency(kpis.totalValue)}</p>
                    <div className="mt-4 pt-4 border-t border-white/10 flex justify-between items-center text-[10px] font-bold">
                        <span>{kpis.count} {t.projects}</span>
                        <span className="bg-white/20 px-2 py-1 rounded-lg uppercase">{selectedMonthYear === 'all' ? 'All Time' : 'Period View'}</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm group">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.collected}</p>
                    <p className="text-3xl font-black text-emerald-500">{formatCurrency(kpis.collected)}</p>
                    <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full mt-6 overflow-hidden">
                        <div className="bg-emerald-500 h-full rounded-full transition-all duration-1000" style={{ width: `${(kpis.collected/kpis.totalValue)*100 || 0}%` }}></div>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.pending}</p>
                    <p className="text-3xl font-black text-orange-500">{formatCurrency(kpis.pending)}</p>
                    <div className="flex items-center gap-1.5 mt-4">
                        <span className="w-1.5 h-1.5 rounded-full bg-orange-500"></span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase">Remaining Balance</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm relative overflow-hidden group">
                    <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                        <svg className="w-16 h-16" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    </div>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{t.activeIssues}</p>
                    <p className="text-3xl font-black text-red-500">{kpis.totalIssues}</p>
                    <div className="mt-4 pt-4 border-t border-slate-50 dark:border-slate-800">
                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter italic">Requires Attention</span>
                    </div>
                </div>
            </div>

            {/* Tree View Roadmap Section */}
            <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-10 gap-4">
                    <div>
                        <h3 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.timelineRoadmap}</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{t.roadmapSubtitle}</p>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
                            <button onClick={expandAll} className="px-3 py-1.5 text-[9px] font-black uppercase text-slate-500 hover:text-violet-600 transition-colors">{t.expandAll}</button>
                            <div className="w-[1px] bg-slate-200 dark:bg-slate-700 mx-1"></div>
                            <button onClick={collapseAll} className="px-3 py-1.5 text-[9px] font-black uppercase text-slate-500 hover:text-violet-600 transition-colors">{t.collapseAll}</button>
                        </div>
                        <div className="text-[10px] font-black text-violet-600 bg-violet-50 dark:bg-violet-900/20 px-4 py-2.5 rounded-xl">
                            {selectedMonthYear === 'all' ? t.allTime : monthYearOptions.find(o => o.value === selectedMonthYear)?.label}
                        </div>
                    </div>
                </div>

                <div className="space-y-4">
                    {Object.keys(groupedHierarchy).length > 0 ? (Object.entries(groupedHierarchy) as [string, any][]).map(([managerId, mGroup]) => {
                        const isMgrExpanded = !!expandedManagers[managerId];
                        const projectList = Object.values(mGroup.projects);

                        return (
                            <div key={managerId} className="relative group/manager">
                                {/* Vertical line for manager depth */}
                                {isMgrExpanded && <div className="absolute left-6 rtl:left-auto rtl:right-6 top-14 bottom-0 w-[1.5px] bg-indigo-100 dark:bg-indigo-900/50"></div>}

                                <div 
                                    onClick={() => toggleManagerExpansion(managerId)} 
                                    className={`p-3 rounded-2xl flex items-center justify-between cursor-pointer transition-all border ${isMgrExpanded ? 'bg-indigo-50/50 border-indigo-200 dark:bg-indigo-900/10 dark:border-indigo-800' : 'bg-white dark:bg-slate-900 border-transparent hover:border-slate-100 dark:hover:border-slate-800'}`}
                                >
                                    <div className="flex items-center gap-4">
                                        <div className={`w-8 h-8 rounded-xl flex items-center justify-center transition-colors ${isMgrExpanded ? 'bg-indigo-600 text-white shadow-lg' : 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-400'}`}>
                                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3">
                                                <path d={isMgrExpanded ? "M19 13H5v-2h14v2z" : "M12 4v16m8-8H4"} />
                                            </svg>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <img src={mGroup.manager?.avatarUrl || `https://ui-avatars.com/api/?name=${mGroup.manager?.name || '?'}&background=6366f1&color=fff`} className="w-10 h-10 rounded-xl border-2 border-white dark:border-slate-800 shadow-sm" alt={mGroup.manager?.name} />
                                            <div>
                                                <h4 className="font-black text-slate-800 dark:text-white uppercase text-xs tracking-tight">{mGroup.manager?.name || t.unassigned}</h4>
                                                <span className="text-[8px] font-black text-indigo-500 uppercase tracking-widest">{projectList.length} {t.projects}</span>
                                            </div>
                                        </div>
                                    </div>
                                    <svg className={`w-4 h-4 text-indigo-300 transition-transform duration-300 ${isMgrExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 9l-7 7-7-7" /></svg>
                                </div>

                                {isMgrExpanded && (
                                    <div className="ps-12 py-3 space-y-3 animate-in slide-in-from-top-2 duration-300">
                                        {projectList.map(({ project, milestones: pMilestones }: any) => {
                                            const isPrjExpanded = !!expandedProjects[project.id];
                                            return (
                                                <div key={project.id} className="relative group/project">
                                                    {/* Horizontal line connector */}
                                                    <div className="absolute -left-6 rtl:-left-auto rtl:-right-6 top-6 w-6 h-[1.5px] bg-indigo-100 dark:bg-indigo-900/50"></div>
                                                    {/* Vertical line for project depth */}
                                                    {isPrjExpanded && <div className="absolute left-6 rtl:left-auto rtl:right-6 top-14 bottom-0 w-[1.5px] bg-violet-100 dark:bg-violet-900/50"></div>}

                                                    <div 
                                                        onClick={() => toggleProjectExpansion(project.id)} 
                                                        className={`p-3 rounded-2xl flex items-center justify-between cursor-pointer transition-all border ${isPrjExpanded ? 'bg-violet-50/50 border-violet-200 dark:bg-violet-900/10 dark:border-violet-800' : 'bg-white dark:bg-slate-900 border-transparent hover:border-slate-50 dark:hover:border-slate-800'}`}
                                                    >
                                                        <div className="flex items-center gap-4 min-w-0">
                                                            <div className={`w-7 h-7 rounded-lg flex items-center justify-center transition-colors ${isPrjExpanded ? 'bg-violet-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                                                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3">
                                                                     <path d={isPrjExpanded ? "M19 13H5v-2h14v2z" : "M12 4v16m8-8H4"} />
                                                                </svg>
                                                            </div>
                                                            <div className="min-w-0">
                                                                <h4 className="font-black text-slate-800 dark:text-white truncate text-[11px] leading-tight">{project.name}</h4>
                                                                <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{project.projectCode}</span>
                                                            </div>
                                                        </div>
                                                        <div className="flex items-center gap-6">
                                                            <div className="text-right min-w-[50px]">
                                                                <p className="text-[8px] font-black text-slate-400 uppercase">{t.progress}</p>
                                                                <p className="text-[10px] font-black text-violet-600">{project.progress}%</p>
                                                            </div>
                                                        </div>
                                                    </div>

                                                    {isPrjExpanded && (
                                                        <div className="ps-10 py-3 space-y-2 animate-in slide-in-from-top-2 duration-300">
                                                            {pMilestones.map((m: any) => (
                                                                <div key={m.id} className="relative group/milestone flex items-center justify-between p-3 bg-white dark:bg-slate-900/40 rounded-xl hover:shadow-md transition-all border border-transparent hover:border-slate-100 dark:hover:border-slate-800">
                                                                    {/* Horizontal connector to milestone */}
                                                                    <div className="absolute -left-4 rtl:-left-auto rtl:-right-4 top-1/2 -translate-y-1/2 w-4 h-[1.5px] bg-violet-100 dark:bg-violet-900/50"></div>

                                                                    <div className="flex items-center gap-3 min-w-0">
                                                                        <div className="w-1.5 h-1.5 rounded-full bg-violet-400 shrink-0 group-hover/milestone:scale-150 transition-transform"></div>
                                                                        <div className="min-w-0">
                                                                            <p className="text-[11px] font-bold text-slate-700 dark:text-slate-200 truncate">{m.title}</p>
                                                                            <div className="flex items-center gap-2 mt-0.5">
                                                                                <span className={`text-[7px] font-black px-1.5 py-0.5 rounded uppercase ${statusColors[m.status as MilestoneStatus]}`}>{t[m.status as MilestoneStatus]}</span>
                                                                                {m.dueDate && <span className="text-[8px] font-bold text-slate-400">{new Date(m.dueDate).toLocaleDateString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short' })}</span>}
                                                                            </div>
                                                                        </div>
                                                                    </div>
                                                                    {m.hasPayment && (
                                                                        <div className="text-right">
                                                                            <p className="text-[10px] font-black text-emerald-600">{formatCurrency(m.paymentAmount)}</p>
                                                                            <p className="text-[7px] font-black text-slate-400 uppercase tracking-tighter">{t[m.paymentStatus as PaymentStatus || 'Pending']}</p>
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            ))}
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        );
                    }) : (
                        <div className="py-20 text-center text-[10px] font-black text-slate-300 uppercase tracking-[0.5em]">{t.noData}</div>
                    )}
                </div>
            </div>

            {/* Task Analysis Section */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Tasks by Project */}
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
