                        );
                    }) : (
                        <div className="py-20 text-center text-[10px] font-black text-slate-300 uppercase tracking-[0.5em]">{t.noData}</div>
                    )}
                </div>
            </div>

            {/* Task Analysis Section */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Tasks by Project */}
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex items-center gap-3 mb-8">
                        <div className="w-10 h-10 bg-red-500/10 rounded-2xl flex items-center justify-center text-red-500">
                             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                        </div>
                        <div>
                            <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-widest">{t.issuesByProject}</h3>
                            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{t.criticalAreas}</p>
                        </div>
                    </div>
                    <div className="space-y-4">
                        {issueStats.byProject.length > 0 ? issueStats.byProject.map((item, idx) => (
                            <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/30 rounded-2xl group hover:bg-red-50 dark:hover:bg-red-900/10 transition-all border border-transparent hover:border-red-100 dark:hover:border-red-800" key={idx}>
                                <span className="text-xs font-black text-slate-700 dark:text-slate-200 truncate pr-4 rtl:pr-0 rtl:pl-4">{item.name}</span>
                                <div className="flex items-center gap-2">
                                    <span className="text-xs font-black text-red-500">{item.count}</span>
                                    <span className="text-[9px] font-black text-slate-400 uppercase">{t.issuesCount}</span>
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-10 text-[10px] font-black text-slate-300 uppercase italic">{t.noIssuesFound}</div>
                        )}
                    </div>
                </div>

                {/* Tasks by User */}
                <div className="bg-white dark:bg-slate-900 p-10 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex items-center gap-3 mb-8">
                        <div className="w-10 h-10 bg-indigo-500/10 rounded-2xl flex items-center justify-center text-indigo-500">
                             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                        </div>
                        <div>
                            <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-widest">{t.issuesByUser}</h3>
                            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{t.teamLoad}</p>
                        </div>
                    </div>
                    <div className="space-y-4">
                        {issueStats.byUser.length > 0 ? issueStats.byUser.map((item, idx) => (
                            <div className="flex items-center gap-3 p-4 bg-slate-50 dark:bg-slate-800/30 rounded-2xl group hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all border border-transparent hover:border-indigo-100 dark:hover:border-indigo-800" key={idx}>
                                <div className="flex items-center gap-3">
                                    <img src={item.avatar || `https://ui-avatars.com/api/?name=${item.name}&background=8b5cf6&color=fff`} className="w-8 h-8 rounded-full border-2 border-white dark:border-slate-800 shadow-sm" />
                                    <span className="text-xs font-black text-slate-700 dark:text-slate-200">{item.name}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <span className="text-xs font-black text-indigo-500">{item.count}</span>
                                    <span className="text-[9px] font-black text-slate-400 uppercase">{t.issuesCount}</span>
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-10 text-[10px] font-black text-slate-300 uppercase italic">{t.noIssuesFound}</div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

