                    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
                        {projectsToDisplay.map(project => (
                            <ProjectCard key={project.id} project={project} onEdit={() => onOpenEditModal(project)} onDelete={() => onOpenDeleteModal(project)} language={language} />
                        ))}
                    </div>
                ) : (
                    <div className="overflow-x-auto custom-scrollbar bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl">
                        <div className="min-w-[1000px] p-4">
                            <div className="flex items-center gap-4 text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 mb-4">
                                <div className="flex-1">PROJECT INFO</div>
                                <div className="w-32 text-center">STATUS</div>
                                <div className="w-24 text-center">SCORE</div>
                                <div className="w-40 text-center">MANAGER</div>
                                <div className="w-40 text-center">CUSTOMER</div>
                                <div className="w-16 text-center">...</div>
                            </div>
                            <div className="space-y-2">
                                {projectsToDisplay.map(project => (
                                    <ProjectListItem key={project.id} project={project} onEdit={() => onOpenEditModal(project)} onDelete={() => onOpenDeleteModal(project)} language={language} visibleColumns={visibleColumns} />
                                ))}
                            </div>
                        </div>
                    </div>
                )
            ) : (
                <p className="text-center text-[10px] font-black uppercase text-slate-300 tracking-[0.5em] py-20">{t.noProjectsFound}</p>
            )}
        </div>
    );
};

