};

export const updateMaintenanceContract = async (id: string, c: any) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const { error } = await supabase.from('maintenance_contracts').update({
        type: c.type, month: c.month, year: c.year, customer_id: c.customerId, project_code: c.project_code, total_amount: c.total_amount, collected_amount: c.collected_amount, lost_amount: c.lost_amount, start_date: c.startDate, end_date: c.endDate, notes: c.notes
    }).eq('id', id);
    if (error) throw error;
